import java.util.Map;

public class ClassX {
    /**
     * Validiert den Token-Header, um sicherzustellen, dass der Algorithmus unterstützt wird.
     * 
     * Die Funktion überprüft, ob das Feld 'alg' im Header 'HS256' enthält.
     *
     * @param header Eine Map, die den Token-Header repräsentiert. Erwartet ein Feld 'alg'.
     * @throws IllegalArgumentException Wenn der Header null ist, das Feld 'alg' fehlt oder der Wert nicht 'HS256' ist.
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null || header.isEmpty()) {
            throw new IllegalArgumentException("Token-Header darf nicht null oder leer sein.");
        }

        String algorithm = header.get("alg");

        if (algorithm == null) {
            throw new IllegalArgumentException("Feld 'alg' fehlt im Token-Header.");
        }

        if (!"HS256".equals(algorithm)) {
            throw new IllegalArgumentException("Nicht unterstützter Algorithmus: '" + algorithm + "'. Nur 'HS256' wird unterstützt.");
        }
    }
}
