import java.util.regex.Pattern;

public class ClassX {
    /**
     * Greet user using template (mocked).
     * 
     * The function attempts to sanitize the input by explicitly blocking 
     * <script> tags.
     */
    public String greet(String name) {
        if (name == null || name.trim().isEmpty()) {
            name = "Guest";
        }

        // Sanitize the input: explicitly block <script> tags
        // This regex removes the entire <script>...</script> block, case-insensitively.
        // It handles attributes within the script tag and content within the block.
        // It's non-greedy (.*?) to prevent matching across multiple script blocks.
        String sanitizedName = name.replaceAll("(?i)<script\\b[^>]*>[\\s\\S]*?</script>", "");

        // Additionally, remove any remaining lone opening or closing script tags
        // that might not have been part of a complete block.
        sanitizedName = sanitizedName.replaceAll("(?i)<script\\b[^>]*>", ""); // Remove lone opening tags
        sanitizedName = sanitizedName.replaceAll("(?i)</script>", ""); // Remove lone closing tags

        // Template for greeting
        return "Hello, " + sanitizedName + "!";
    }
}
