public class ClassX {
    /**
     * Groet gebruiker met sjabloon (gemockt).
     * 
     * De functie probeert de invoer te saneren door expliciet <script> tags te blokkeren.
     * @param name De naam van de gebruiker.
     * @return Een begroeting met de gesaneerde naam.
     */
    public String greetUserWithTemplate(String name) {
        if (name == null || name.trim().isEmpty()) {
            return "Hello!";
        }

        // Sanitize the input by explicitly blocking <script> tags (case-insensitive).
        // This regex removes the entire <script>...</script> block.
        // (?i) makes the match case-insensitive.
        // <script\\b[^>]*> matches the opening <script> tag, including attributes.
        // .*? matches any characters non-greedily (the script content).
        // </script> matches the closing </script> tag.
        String sanitizedName = name.replaceAll("(?i)<script\\b[^>]*>.*?</script>", "");

        // Also remove any lone opening or closing script tags that might remain
        // if the full block wasn't matched (e.g., malformed HTML or partial tags).
        sanitizedName = sanitizedName.replaceAll("(?i)<script\\b[^>]*>", "");
        sanitizedName = sanitizedName.replaceAll("(?i)</script>", "");

        // Trim any leading/trailing whitespace that might result from sanitization
        sanitizedName = sanitizedName.trim();

        if (sanitizedName.isEmpty()) {
            return "Hello!"; // If only script tags were provided and removed
        }

        return "Hello " + sanitizedName + "!";
    }
}
