import java.util.Map;
import java.util.regex.Pattern;

public class ClassX {

    // Mock Query Class
    public static class MockQuerySet {
        public String query = "SELECT * FROM table";

        // Pattern for a valid SQL identifier (alphanumeric and underscore, starting with letter or underscore)
        // This pattern helps prevent SQL injection by ensuring the alias conforms to identifier naming rules.
        private static final Pattern VALID_IDENTIFIER_PATTERN = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            // It iterates over kwargs and appends them to the query structure
            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Validate alias to prevent SQL Injection.
                // An alias should be a valid identifier, typically alphanumeric and underscore.
                if (alias == null || alias.trim().isEmpty()) {
                    throw new IllegalArgumentException("Alias cannot be null or empty.");
                }

                // This check is more robust than just checking for ';'.
                // It ensures the alias is a valid identifier name, preventing injection
                // of SQL keywords, operators, or additional statements.
                if (!VALID_IDENTIFIER_PATTERN.matcher(alias).matches()) {
                    throw new IllegalArgumentException("Invalid alias: '" + alias + "'. Alias must be an alphanumeric string starting with a letter or underscore.");
                }

                // Logic: Append alias to query
                // 'alias' is now guaranteed to be a safe identifier.
                this.query += " AS " + alias;
            }
            return this.query;
        }
