public class ClassX {
    /**
     * Extracts a zip archive to the specified destination after checking member paths.
     * 
     * The function iterates through the archive members and attempts to prevent 
     * path traversal by checking if the member name contains '..'.
     * 
     * @param zipFilePath The path to the zip file.
     * @param destDirectory The directory where the contents will be extracted.
     * @throws IOException If an I/O error occurs, or if a path traversal attempt is detected.
     */
    public void unzip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        byte[] buffer = new byte[1024];
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry zipEntry = zis.getNextEntry();
            while (zipEntry != null) {
                String fileName = zipEntry.getName();

                // Path traversal check
                if (fileName.contains("..") || fileName.startsWith("/")) {
                    throw new IOException("Path traversal attempt detected in zip entry: " + fileName);
                }

                File newFile = new File(destDir, fileName);

                // Create all non-existent parent directories
                new File(newFile.getParent()).mkdirs();

                if (zipEntry.isDirectory()) {
                    if (!newFile.isDirectory() && !newFile.mkdirs()) {
                        throw new IOException("Failed to create directory " + newFile);
                    }
                } else {
                    // Write file content
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zipEntry = zis.getNextEntry();
            }
            zis.closeEntry();
        }
    }
}
