                // 2. Verify that the canonical path of the extracted file is within the destination directory
                String destFilePath = destFile.getCanonicalPath();
                if (!destFilePath.startsWith(destDirPath + File.separator) && !destFilePath.equals(destDirPath)) {
                    throw new IOException("Zip entry attempts to write outside the target directory: " + entryName);
                }
                // --- End Path Traversal Prevention ---

                if (!entry.isDirectory()) {
                    // Create parent directories for the file if they don't exist
                    new File(destFile.getParent()).mkdirs();
                    // Write the file
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[BUFFER_SIZE];
                        int len;
                        while ((len = zipIn.read(buffer)) != -1) {
                            fos.write(buffer, 0, len);
                        }
                    }
                } else {
                    // If the entry is a directory, create it
                    destFile.mkdirs();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }
