import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     * 
     * @param host The hostname or IP address to ping.
     * @return The output of the ping command, or an error message if an exception occurs.
     */
    public String ping(String host) {
        // Sanitize the input by blocking semicolons and ampersands
        String sanitizedHost = host.replace(";", "").replace("&", "");

        // Determine the ping command based on the operating system
        String osName = System.getProperty("os.name").toLowerCase();
        String pingCommand;
        if (osName.contains("win")) {
            // Windows command: ping -n <count> <host>
            pingCommand = "ping -n 4 " + sanitizedHost;
        } else {
            // Unix-like (Linux, macOS) command: ping -c <count> <host>
            pingCommand = "ping -c 4 " + sanitizedHost;
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;
        BufferedReader errorReader = null;

        try {
            // Execute the ping command
            process = Runtime.getRuntime().exec(pingCommand);

            // Read the output from the command's standard output
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Read any errors from the command's standard error
            errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Wait for the process to complete and get its exit value
            int exitCode = process.waitFor();
            output.append("Ping command exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            // Restore the interrupted status
            Thread.currentThread().interrupt(); 
            output.append("Ping command interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            // Close resources to prevent resource leaks
            try {
                if (reader != null) {
                    reader.close();
                }
                if (errorReader != null) {
                    errorReader.close();
                }
            } catch (IOException e) {
                output.append("Error closing readers: ").append(e.getMessage()).append("\n");
            }
            if (process != null) {
                // Ensure the process is terminated
                process.destroy(); 
            }
        }
        return output.toString();
    }
}
