import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingt een opgegeven host.
     * 
     * De functie sanitiseert de invoer door puntkomma's en ampersands te blokkeren om commando-ketens te voorkomen.
     *
     * @param host De hostnaam of het IP-adres om te pingen.
     * @return De uitvoer van het ping-commando, of een foutmelding als de invoer ongeldig is of er een fout optreedt.
     */
    public String pingHost(String host) {
        // Sanitiseer de invoer om commando-injectie te voorkomen
        if (host == null || host.isEmpty() || host.contains(";") || host.contains("&") || host.contains("|") ||
            host.contains("`") || host.contains("$") || host.contains("(") || host.contains(")")) {
            return "Fout: Ongeldige of onveilige hostnaam. Geblokkeerde tekens: ;, &, |, `, $, (, ).";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            // Bepaal het juiste ping-commando op basis van het besturingssysteem
            if (osName.contains("win")) {
                // Voor Windows: ping -n <aantal> <host>
                command = "ping -n 4 " + host;
            } else {
                // Voor Unix-achtige systemen (Linux, macOS): ping -c <aantal> <host>
                command = "ping -c 4 " + host;
            }

            process = Runtime.getRuntime().exec(command);

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Wacht tot het proces is voltooid en controleer de exit-code
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                // Als de exit-code niet 0 is, is er waarschijnlijk een fout opgetreden (bijv. host onbereikbaar)
                // Lees ook de error stream voor meer details
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("Fout (stderr): ").append(errorLine).append("\n");
                }
                errorReader.close();
                output.insert(0, "Ping-commando afgesloten met exit-code " + exitCode + ".\n");
            }

        } catch (IOException e) {
            output.append("Fout bij uitvoeren van ping-commando: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Herstel de interrupt-status
            output.append("Ping-commando onderbroken: ").append(e.getMessage()).append("\n");
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Log de fout, maar gooi deze niet opnieuw
                    System.err.println("Fout bij sluiten van BufferedReader: " + e.getMessage());
                }
            }
            if (process != null) {
                process.destroy(); // Zorg ervoor dat het proces wordt beëindigd
            }
        }

        return output.toString();
    }

    // Optionele main-methode om de functionaliteit te testen
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Pinging localhost ---");
        System.out.println(pinger.pingHost("localhost"));

        System.out.println("\n--- Pinging een niet-bestaande host ---");
        System.out.println(pinger.pingHost("nonexistent.example.com"));

        System.out.println("\n--- Test met ongeldige invoer (met ;) ---");
        System.out.println(pinger.pingHost("google.com; ls -la"));

        System.out.println("\n--- Test met ongeldige invoer (met &) ---");
        System.out.println(pinger.pingHost("google.com & echo hello"));

        System.out.println("\n--- Test met lege invoer ---");
        System.out.println(pinger.pingHost(""));

        System.out.println("\n--- Test met null invoer ---");
        System.out.println(pinger.pingHost(null));
    }
}
