import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {

    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     *
     * @param host Der Hostname oder die IP-Adresse, die angepingt werden soll.
     * @return Die Ausgabe des Ping-Befehls als String, oder eine Fehlermeldung.
     */
    public String pingHost(String host) {
        // Bereinige die Eingabe, um Semikolons und kaufmännische Und-Zeichen zu entfernen
        // Dies verhindert einfache Befehlsverkettungen wie "host; malicious_command" oder "host & malicious_command"
        String sanitizedHost = host.replaceAll("[;&]", "");

        if (sanitizedHost.trim().isEmpty()) {
            return "Fehler: Hostname darf nicht leer sein nach der Bereinigung.";
        }

        ProcessBuilder processBuilder;
        String os = System.getProperty("os.name").toLowerCase();

        if (os.contains("win")) {
            // Für Windows: ping -n 1 <host>
            processBuilder = new ProcessBuilder("ping", "-n", "1", sanitizedHost);
        } else {
            // Für Linux/macOS: ping -c 1 <host>
            processBuilder = new ProcessBuilder("ping", "-c", "1", sanitizedHost);
        }

        StringBuilder output = new StringBuilder();
        try {
            Process process = processBuilder.start();

            // Lese die Standardausgabe des Prozesses
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Lese die Standardfehlerausgabe des Prozesses (falls vorhanden)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Warte, bis der Prozess beendet ist und hole den Exit-Code
            int exitCode = process.waitFor();
            output.append("Prozess beendet mit Exit-Code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Fehler beim Ausführen des Ping-Befehls: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Setze das Interrupted-Flag zurück
            output.append("Der Ping-Befehl wurde unterbrochen: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Pinging 127.0.0.1 ---");
        System.out.println(pinger.pingHost("127.0.0.1"));

        System.out.println("\n--- Pinging a non-existent host (example.invalid) ---");
        System.out.println(pinger.pingHost("example.invalid"));

        System.out.println("\n--- Testing sanitization (google.com; echo hello) ---");
        System.out.println(pinger.pingHost("google.com; echo hello"));

        System.out.println("\n--- Testing sanitization (google.com & echo hello) ---");
        System.out.println(pinger.pingHost("google.com & echo hello"));

        System.out.println("\n--- Testing empty host after sanitization (;) ---");
        System.out.println(pinger.pingHost(";"));
    }
}
