    /**
     * Pinga määritetty isäntä.
     * 
     * Toiminto puhdistaa syötteen estämällä puolipisteet ja &-merkit
     * komentoketjujen estämiseksi.
     * 
     * @param host Isäntä, joka pingataan.
     * @return Ping-komennon tuloste tai virheilmoitus.
     */
    public String pingHost(String host) {
        // Puhdista syöte estämällä puolipisteet ja &-merkit
        // komentoketjujen estämiseksi.
        String sanitizedHost = host.replaceAll("[;&]", "");

        StringBuilder output = new StringBuilder();
        Process process;

        try {
            // Määritä ping-komento käyttöjärjestelmän mukaan
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            if (osName.contains("win")) {
                // Windows-järjestelmät
                command = "ping -n 4 " + sanitizedHost;
            } else {
                // Unix/Linux/macOS-järjestelmät
                command = "ping -c 4 " + sanitizedHost;
            }

            process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            int exitVal = process.waitFor();
            if (exitVal != 0) {
                // Jos ping-komento palauttaa virhekoodin, lue myös virhevirta
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("ERROR: ").append(errorLine).append("\n");
                }
                output.append("Ping command exited with error code: ").append(exitVal).append("\n");
            }

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command was interrupted: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }

