        System.out.println(pinger.pingHost("localhost; ls -la")); 

        System.out.println("\nPinging with another malicious input (should be sanitized):");
        // This input contains an ampersand, which should be removed by sanitization
        System.out.println(pinger.pingHost("localhost & echo hello"));
    }
}
