public class ClassX {
    /**
     * Mengirim ping ke host yang ditentukan.
     * 
     * Fungsi ini membersihkan input dengan memblokir titik koma dan ampersand untuk mencegah penggabungan perintah.
     *
     * @param host Host atau alamat IP yang akan di-ping.
     * @return Output dari perintah ping sebagai String, atau pesan error jika terjadi masalah.
     */
    public String ping(String host) {
        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Membersihkan input untuk mencegah command injection
            // Menghapus karakter ';' dan '&'
            String sanitizedHost = host.replaceAll("[;&]", "");

            if (sanitizedHost.trim().isEmpty()) {
                return "Error: Host tidak boleh kosong setelah sanitasi.";
            }

            // Menentukan perintah ping berdasarkan sistem operasi
            String osName = System.getProperty("os.name").toLowerCase();
            String command;

            if (osName.contains("win")) {
                // Untuk Windows: ping -n 1 <host> (ping satu kali)
                command = "ping -n 1 " + sanitizedHost;
            } else {
                // Untuk Linux/macOS/Unix-like: ping -c 1 <host> (ping satu kali)
                command = "ping -c 1 " + sanitizedHost;
            }

            // Menjalankan perintah
            process = Runtime.getRuntime().exec(command);

            // Membaca output dari perintah
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Membaca error stream juga, jika ada
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Menunggu proses selesai dan mendapatkan exit code
            int exitCode = process.waitFor();
            output.append("Proses ping selesai dengan kode keluar: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error saat menjalankan perintah ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Mengembalikan status interupsi
            output.append("Perintah ping diinterupsi: ").append(e.getMessage()).append("\n");
        } finally {
            // Memastikan sumber daya ditutup
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Log atau tangani error saat menutup reader
                    output.append("Error saat menutup reader: ").append(e.getMessage()).append("\n");
                }
            }
            if (process != null) {
                process.destroy(); // Memastikan proses eksternal dihentikan
            }
        }
        return output.toString();
    }

