        }

        String os = System.getProperty("os.name").toLowerCase();
        String command;
        String countFlag;

        // Determina o comando ping e a flag de contagem com base no sistema operacional
        if (os.contains("win")) {
            command = "ping";
            countFlag = "-n"; // Para Windows
        } else {
            command = "ping";
            countFlag = "-c"; // Para Linux/macOS
        }

        // Constrói o comando a ser executado
        // Ex: "ping -c 1 google.com" ou "ping -n 1 google.com"
        ProcessBuilder processBuilder = new ProcessBuilder(command, countFlag, "1", host);
