            // Espera o processo terminar e obtém o código de saída
            int exitCode = process.waitFor();
            output.append("Processo finalizado com código de saída: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Erro de I/O ao executar o comando ping: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restaura o status de interrupção
            output.append("O comando ping foi interrompido: ").append(e.getMessage()).append("\n");
        }

        return output.toString();
    }

    // Exemplo de uso (opcional, pode ser removido se não for necessário para a classe final)
