import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    /**
     * Pingea un host especificado.
     * 
     * La función sanitiza la entrada bloqueando punto y coma y ampersands para prevenir la encadenación de comandos.
     */
    public void pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            System.out.println("Error: El host no puede estar vacío.");
            return;
        }

        // Sanitización de la entrada: Bloquear caracteres que permiten la encadenación de comandos.
        // Se bloquean punto y coma, ampersands, barras verticales, comillas invertidas,
        // signos de dólar y paréntesis, que son comunes en ataques de inyección de comandos.
        if (host.contains(";") || host.contains("&") || host.contains("|") ||
            host.contains("`") || host.contains("$") || host.contains("(") || host.contains(")")) {
            System.out.println("Error de seguridad: Caracteres inválidos detectados en el host. Intento de inyección de comandos bloqueado.");
            return;
        }

        List<String> command = new ArrayList<>();
        String os = System.getProperty("os.name").toLowerCase();

        if (os.contains("win")) {
            // Para Windows
            command.add("cmd.exe");
            command.add("/c");
            command.add("ping");
            command.add("-n"); // Número de solicitudes de eco a enviar
            command.add("1");  // Enviar solo 1 paquete
            command.add(host);
        } else {
            // Para sistemas basados en Unix (Linux, macOS)
            command.add("ping");
            command.add("-c"); // Número de paquetes a enviar
            command.add("1");  // Enviar solo 1 paquete
            command.add(host);
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true); // Redirige el error stream al output stream

        try {
            Process process = processBuilder.start();

            // Leer la salida del comando
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Esperar a que el proceso termine y obtener el código de salida
            int exitCode = process.waitFor();
            System.out.println("\nComando 'ping' finalizado con código de salida: " + exitCode);

        } catch (IOException e) {
            System.err.println("Error al ejecutar el comando 'ping': " + e.getMessage());
            e.printStackTrace();
        } catch (InterruptedException e) {
            System.err.println("El comando 'ping' fue interrumpido: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restaura el estado de interrupción
        }
    }

