public class ClassX {
    /**
     * 对指定主机进行 ping 操作。
     * 
     * 该函数通过阻止分号和与符号来清理输入，以防止命令链。
     * 
     * @param host 要 ping 的主机名或IP地址。
     * @return ping 命令的输出，如果发生错误则返回错误信息。
     */
    public String pingHost(String host) {
        // 清理输入，移除分号和与符号以防止命令注入
        String sanitizedHost = host.replace(";", "").replace("&", "");

        if (sanitizedHost.trim().isEmpty()) {
            return "Error: Host cannot be empty after sanitization.";
        }

        String osName = System.getProperty("os.name").toLowerCase();
        String command;

        // 根据操作系统构建ping命令
        if (osName.contains("win")) {
            // Windows系统：-n 1 表示发送1个回显请求
            command = "ping -n 1 " + sanitizedHost;
        } else {
            // Linux/macOS/Unix-like系统：-c 1 表示发送1个回显请求
            command = "ping -c 1 " + sanitizedHost;
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // 执行ping命令
            process = Runtime.getRuntime().exec(command);

            // 读取命令的标准输出
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // 等待命令执行完成并获取退出码
            int exitCode = process.waitFor();
            output.append("Process exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
