    /**
     * یک میزبان مشخص را پینگ می‌کند.
     * 
     * این تابع ورودی را با مسدود کردن نقطه‌ویرگول‌ها و نشانه‌های و، پاک‌سازی می‌کند تا از زنجیره‌ای شدن دستورات جلوگیری کند.
     *
     * @param host نام میزبان یا آدرس IP برای پینگ کردن.
     * @return خروجی دستور پینگ یا یک پیام خطا در صورت بروز مشکل.
     */
    public String pingHost(String host) {
        // پاک‌سازی ورودی برای جلوگیری از زنجیره‌ای شدن دستورات
        // حذف نقطه‌ویرگول‌ها، نشانه‌های و، و سایر کاراکترهای خطرناک
        String sanitizedHost = host.replaceAll("[;&|`$()<>{}!\\[\\]\\\\\"']", "");

        // بررسی اینکه آیا میزبان پس از پاک‌سازی خالی نیست
        if (sanitizedHost.trim().isEmpty()) {
            return "خطا: نام میزبان پس از پاک‌سازی نامعتبر است.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        try {
            // ساخت دستور پینگ. برای سیستم‌عامل‌های مختلف ممکن است متفاوت باشد.
            // برای ویندوز: ping -n 1 <host>
            // برای لینوکس/macOS: ping -c 1 <host>
            String os = System.getProperty("os.name").toLowerCase();
            ProcessBuilder processBuilder;

            if (os.contains("win")) {
                processBuilder = new ProcessBuilder("ping", "-n", "1", sanitizedHost);
            } else { // فرض بر لینوکس یا macOS
                processBuilder = new ProcessBuilder("ping", "-c", "1", sanitizedHost);
            }

            process = processBuilder.start();

            // خواندن خروجی استاندارد
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
            }

            // خواندن خطاهای استاندارد (در صورت وجود)
            try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String errorLine;
                while ((errorLine = errorReader.readLine()) != null) {
                    output.append("خطا: ").append(errorLine).append("\n");
                }
            }

            // منتظر ماندن برای اتمام فرآیند و دریافت کد خروج
            int exitCode = process.waitFor();
            output.append("کد خروج: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("خطا در اجرای دستور پینگ: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // بازیابی وضعیت وقفه
            output.append("عملیات پینگ قطع شد: ").append(e.getMessage()).append("\n");
        } finally {
            if (process != null) {
                process.destroy(); // اطمینان از پایان فرآیند
            }
        }
        return output.toString();
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- پینگ google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- پینگ 127.0.0.1 ---");
        System.out.println(pinger.pingHost("127.0.0.1"));

        System.out.println("\n--- تلاش برای تزریق دستور (ناموفق) ---");
        // این ورودی باید پاک‌سازی شود و فقط "google.com" پینگ شود
        System.out.println(pinger.pingHost("google.com; ls -la"));

        System.out.println("\n--- تلاش برای تزریق دستور دیگر (ناموفق) ---");
        System.out.println(pinger.pingHost("localhost & echo hello"));

        System.out.println("\n--- پینگ یک میزبان ناموجود (احتمالاً) ---");
        System.out.println(pinger.pingHost("nonexistent.domain.xyz"));

        System.out.println("\n--- ورودی خالی یا فقط کاراکترهای خطرناک ---");
        System.out.println(pinger.pingHost(";;&&||"));
    }
}
