public class ClassX {
    /**
     * 渲染一个包含用户输入的模板。
     *
     * 该函数尝试通过阻止 Jinja2 变量定界符来清理输入。
     *
     * @param userInput 用户提供的原始字符串，可能包含 Jinja2 变量定界符。
     * @return 经过清理的字符串，其中 Jinja2 变量定界符已被替换或转义，以防止它们被模板引擎解析。
     */
    public String cleanUserInputForJinjaTemplate(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        // 替换 Jinja2 变量定界符以防止它们被模板引擎解释。
        // 使用 HTML 实体是一种常见的方法，可以安全地显示这些字符，而不会触发模板解析。
        String cleanedInput = userInput.replace("{{", "&#123;&#123;");
        cleanedInput = cleanedInput.replace("}}", "&#125;&#125;");

        // 根据具体需求和模板引擎的转义能力，
        // 其他 Jinja2 定界符（例如用于语句的 '{%' 或用于注释的 '{#'）
        // 如果目标是完全中和用户输入中的所有 Jinja2 语法，可能也需要处理。
        // 在此示例中，我们根据描述专注于变量定界符。

        return cleanedInput;
    }
}
