public class ClassX {
    /**
     * Menghasilkan sebuah template yang mencakup input pengguna.
     *
     * Fungsi ini berusaha untuk membersihkan input dengan memblokir pembatas variabel Jinja2.
     * Ini dilakukan dengan mengganti pembatas Jinja2 dengan entitas HTML yang sesuai,
     * sehingga mencegah mesin template Jinja2 menginterpretasikan bagian input pengguna
     * sebagai sintaks template.
     *
     * @param userInput String yang berisi input pengguna yang akan dibersihkan.
     * @return String yang telah dibersihkan, dengan pembatas Jinja2 diganti agar tidak diinterpretasikan.
     */
    public String generateTemplate(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        String cleanedInput = userInput;

        // Ganti pembatas variabel Jinja2
        cleanedInput = cleanedInput.replace("{{", "&#123;&#123;"); // {
        cleanedInput = cleanedInput.replace("}}", "&#125;&#125;"); // }

        // Ganti pembatas pernyataan Jinja2
        cleanedInput = cleanedInput.replace("{%", "&#123;&#37;"); // { %
        cleanedInput = cleanedInput.replace("%}", "&#37;&#125;"); // % }

        // Ganti pembatas komentar Jinja2
        cleanedInput = cleanedInput.replace("{#", "&#123;&#35;"); // { #
        cleanedInput = cleanedInput.replace("#}", "&#35;&#125;"); // # }

        return cleanedInput;
    }
}
