    private String sanitizeJinja2VariableDelimiters(String input) {
        // Ersetze öffnende Variablenbegrenzer
        String sanitized = input.replace("{{", "{ {");
        // Ersetze schließende Variablenbegrenzer
        sanitized = sanitized.replace("}}", "} }");
        return sanitized;
    }

