     * @param userInput Die rohe Benutzereingabe, die in die Vorlage eingefügt werden soll.
     * @return Die gerenderte Vorlage mit bereinigter Benutzereingabe.
     */
    public String renderTemplate(String template, String userInput) {
        String sanitizedInput = sanitizeJinja2VariableDelimiters(userInput);

