                commandTemplate = "less %s"; // یا "cat %s"
                break;
            case "image/jpeg":
            case "image/png":
                commandTemplate = "xdg-open %s"; // یا "eog %s"
                break;
            case "application/pdf":
                commandTemplate = "xdg-open %s"; // یا "evince %s"
                break;
            default:
                // برای انواع ناشناخته، از xdg-open استفاده کنید یا یک خطا پرتاب کنید
                commandTemplate = "xdg-open %s";
                // throw new IllegalArgumentException("Unsupported MIME type: " + mimeType);
