import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simule la fonction mailcap.findmatch. 
     * Construit une commande pour afficher le fichier en fonction du mime_type et l'exécute.
     * 
     * Cette implémentation inclut une vérification pour empêcher la chaîne de commandes en bloquant les points-virgules.
     * 
     * @param mimeType Le type MIME du fichier à afficher.
     * @param filePath Le chemin du fichier à afficher.
     * @return true si la commande a été exécutée avec succès, false sinon.
     */
    public boolean findAndExecuteMatch(String mimeType, String filePath) {
        // Simple validation to prevent command chaining via semicolons
        if (mimeType == null || mimeType.contains(";") || filePath == null || filePath.contains(";")) {
            System.err.println("Invalid input: Semicolons are not allowed in mimeType or filePath.");
            return false;
        }

        // In a real mailcap implementation, you would parse mailcap files
        // (e.g., /etc/mailcap, ~/.mailcap) to find the appropriate command.
        // For this simulation, we'll use a very basic hardcoded mapping or a simple heuristic.

        String command = null;

        // Basic example mapping
        if (mimeType.startsWith("image/")) {
            command = "xdg-open " + filePath; // Common on Linux for opening files
        } else if (mimeType.startsWith("text/")) {
            command = "less " + filePath; // For text files
        } else if (mimeType.equals("application/pdf")) {
            command = "xdg-open " + filePath; // For PDFs
        } else {
            System.err.println("No specific handler found for MIME type: " + mimeType);
            return false;
        }

        if (command != null) {
            System.out.println("Executing command: " + command);
            try {
                Process process = Runtime.getRuntime().exec(command);

                // Optionally, read process output/error streams
                BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String s;
                while ((s = stdInput.readLine()) != null) {
                    System.out.println(s);
                }
                while ((s = stdError.readLine()) != null) {
                    System.err.println(s);
                }

                int exitCode = process.waitFor();
                System.out.println("Command exited with code: " + exitCode);
                return exitCode == 0; // Return true if command exited successfully
            } catch (IOException e) {
                System.err.println("Error executing command: " + e.getMessage());
                e.printStackTrace();
            } catch (InterruptedException e) {
                System.err.println("Command execution interrupted: " + e.getMessage());
                Thread.currentThread().interrupt(); // Restore the interrupted status
            }
        }
        return false;
    }

    public static void main(String[] args) {
        ClassX mailcapSimulator = new ClassX();

        // Test cases
        System.out.println("--- Test Case 1: Image ---");
        mailcapSimulator.findAndExecuteMatch("image/jpeg", "/path/to/your/image.jpg"); // Replace with a real path

        System.out.println("\n--- Test Case 2: Text File ---");
        mailcapSimulator.findAndExecuteMatch("text/plain", "/path/to/your/document.txt"); // Replace with a real path

        System.out.println("\n--- Test Case 3: PDF File ---");
        mailcapSimulator.findAndExecuteMatch("application/pdf", "/path/to/your/document.pdf"); // Replace with a real path

        System.out.println("\n--- Test Case 4: Unknown MIME Type ---");
        mailcapSimulator.findAndExecuteMatch("application/octet-stream", "/path/to/some/binary.bin");

        System.out.println("\n--- Test Case 5: Command Injection Attempt (Semicolon in mimeType) ---");
        mailcapSimulator.findAndExecuteMatch("image/jpeg; rm -rf /", "/path/to/image.jpg");

        System.out.println("\n--- Test Case 6: Command Injection Attempt (Semicolon in filePath) ---");
        mailcapSimulator.findAndExecuteMatch("text/plain", "/path/to/document.txt; echo 'injected'");

        System.out.println("\n--- Test Case 7: Non-existent file (command might still run, but fail) ---");
        mailcapSimulator.findAndExecuteMatch("image/png", "/non/existent/file.png");
    }
}
