    public boolean findAndExecuteMatch(String mimeType, String filePath) throws IOException, InterruptedException {
        if (mimeType == null || mimeType.trim().isEmpty()) {
            System.err.println("Error: MIME type cannot be null or empty.");
            return false;
        }
        if (filePath == null || filePath.trim().isEmpty()) {
            System.err.println("Error: File path cannot be null or empty.");
            return false;
