public class ClassX {
    /**
     * Simuloi mailcap.findmatch-funktiota. 
     * Rakentaa komennon tiedoston katsomista varten mime_typen perusteella ja suorittaa sen.
     * 
     * Tässä toteutuksessa on tarkistus, joka estää komentoketjuttamisen estämällä puolipisteet.
     *
     * @param mimeType MIME-tyyppi tiedostolle (esim. "text/plain", "image/jpeg").
     * @param filePath Polku tiedostoon, joka avataan.
     * @throws IllegalArgumentException Jos mimeType tai filePath on null/tyhjä, tai jos filePath sisältää puolipisteitä.
     * @throws IOException Jos komennon suorittamisessa tapahtuu virhe.
     * @throws InterruptedException Jos prosessi keskeytetään odottaessaan.
     */
    public void findMatchAndExecute(String mimeType, String filePath) 
            throws IllegalArgumentException, IOException, InterruptedException {

        if (mimeType == null || mimeType.trim().isEmpty()) {
            throw new IllegalArgumentException("MIME type cannot be null or empty.");
        }
        if (filePath == null || filePath.trim().isEmpty()) {
            throw new IllegalArgumentException("File path cannot be null or empty.");
        }

        // Turvatarkastus: Estä komentoketjutus tarkistamalla puolipisteet tiedostopolusta.
        // Tämä estää käyttäjää syöttämästä esim. "my_file.txt; rm -rf /"
        if (filePath.contains(";")) {
            throw new IllegalArgumentException("File path contains a semicolon (';'), which is not allowed for security reasons.");
        }

        // Vaikka mimeType ei ole suoraan komennon argumentti, on hyvä käytäntö tarkistaa sekin.
        if (mimeType.contains(";")) {
            throw new IllegalArgumentException("MIME type contains a semicolon (';'), which is not allowed for security reasons.");
        }

        String commandExecutable;

        // Yksinkertainen MIME-tyypin ja komennon vastaavuus.
