public class ClassX {
    /**
     * Fetches content from a generated URL after validating the host.
     *
     * This function sanitizes the host by checking for invalid characters like spaces.
     *
     * @param host The host part of the URL (e.g., "example.com").
     * @param path The path part of the URL (e.g., "/api/data").
     * @return The content fetched from the URL as a String.
     * @throws IOException If an I/O error occurs during URL connection or reading,
     *                     or if the host is invalid (e.g., contains spaces, is null or empty).
     */
    public String fetchContent(String host, String path) throws IOException {
        // 1. Validate and sanitize the host
        if (host == null || host.trim().isEmpty()) {
            throw new IOException("Host cannot be null or empty.");
        }

        String sanitizedHost = host.trim(); // Remove leading/trailing whitespace

        // Check for invalid characters like spaces within the host string
        // A more comprehensive validation might use a regular expression for valid domain names,
        // but for this example, we specifically check for spaces as requested.
        if (sanitizedHost.contains(" ")) {
            throw new IOException("Host contains invalid characters (spaces).");
        }

        // 2. Construct the URL
        URL url;
        try {
            // Using HTTPS for secure communication as a best practice
            url = new URL("https", sanitizedHost, path);
        } catch (MalformedURLException e) {
            throw new IOException("Failed to construct a valid URL with host '" + sanitizedHost + "' and path '" + path + "': " + e.getMessage(), e);
        }

        // 3. Open connection and fetch content
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();

            // Set connection timeouts to prevent indefinite waits
            connection.setConnectTimeout(5000); // 5 seconds to establish connection
            connection.setReadTimeout(10000);   // 10 seconds to read data

            // Use try-with-resources to ensure the BufferedReader and InputStreamReader are closed automatically
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            throw new IOException("Failed to fetch content from URL: " + url.toString() + ". Error: " + e.getMessage(), e);
        }

        return content.toString();
    }
}
