public class ClassX {
    /**
     * 在验证主机后，从生成的 URL 获取内容。
     * 
     * 此函数通过检查空格等无效字符来清理主机。
     *
     * @param host 待清理和验证的主机字符串。例如：" www.example.com " 或 "example.com/path"。
     * @return 从 URL 获取的内容字符串。
     * @throws IOException 如果在创建 URL 或读取内容时发生 I/O 错误。
     */
    public String getContentFromUrl(String host) throws IOException {
        // 1. 清理主机字符串
        // 移除前导/尾随空格
        String cleanedHost = host.trim();

        // 确保主机字符串以 http:// 或 https:// 开头。
        // 如果不是，则默认添加 http:// 以形成一个有效的 URL 结构。
        if (!cleanedHost.startsWith("http://") && !cleanedHost.startsWith("https://")) {
            cleanedHost = "http://" + cleanedHost;
        }

        URL url;
        try {
            // 2. 从清理后的主机字符串创建 URL 对象
            url = new URL(cleanedHost);
        } catch (MalformedURLException e) {
            // 如果清理后的主机字符串仍然无法形成一个有效的 URL，则抛出 IOException。
            throw new IOException("Invalid URL format after cleaning host: " + cleanedHost, e);
        }

        StringBuilder content = new StringBuilder();
        // 3. 打开连接并读取内容
        // 使用 try-with-resources 确保 InputStream 和 BufferedReader 资源在操作完成后自动关闭。
        try (InputStream is = url.openStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(is))) {

            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } // try-with-resources 块结束时，is 和 reader 会自动关闭

        return content.toString();
    }
}
