            throw new IOException("Invalid URL format for host: " + host + ". Cleaned host: " + cleanedHost, e);
        }

        StringBuilder content = new StringBuilder();
        // 使用 try-with-resources 确保 BufferedReader 和 InputStreamReader 被正确关闭
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
                content.append(System.lineSeparator()); // 保持原始换行符
