public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     *
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     *
     * @param host De hostnaam om te valideren en te gebruiken.
     * @param path Het pad van de URL.
     * @return De inhoud van de URL als een String.
     * @throws IllegalArgumentException Als de host ongeldige tekens bevat of leeg is.
     * @throws IOException Als er een fout optreedt bij het openen van de verbinding of het lezen van de inhoud.
     */
    public String getContentFromValidatedUrl(String host, String path) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host kan niet null of leeg zijn.");
        }
        if (host.contains(" ")) {
            throw new IllegalArgumentException("Host bevat ongeldige tekens (spaties).");
        }

        URL url;
        try {
            // Gebruik HTTPS als standaard voor veiligheid.
            // Zorg ervoor dat het pad begint met een '/'
            String fullUrlString = "https://" + host + (path.startsWith("/") ? path : "/" + path);
            url = new URL(fullUrlString);
        } catch (MalformedURLException e) {
            throw new IOException("Fout bij het genereren van de URL: " + e.getMessage(), e);
        }

        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            connection.setConnectTimeout(5000); // 5 seconden verbindingstime-out
            connection.setReadTimeout(10000);  // 10 seconden lees-time-out

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line);
                    content.append(System.lineSeparator());
                }
            }
        } catch (IOException e) {
            throw new IOException("Fout bij het ophalen van inhoud van URL: " + url.toString() + ". " + e.getMessage(), e);
        }

        return content.toString();
    }
}
