    /**
     * Извлича съдържание от генериран URL след валидиране на хоста.
     *
     * Тази функция почиства хоста, като проверява за невалидни символи като интервали.
     *
     * @param host Хостът, от който да се извлече съдържание.
     * @param path Пътят до ресурса на хоста.
     * @return Съдържанието на URL като низ.
     * @throws IllegalArgumentException Ако хостът е невалиден или празен.
     * @throws IOException Ако възникне грешка при свързване или четене от URL.
     */
    public String retrieveContentFromGeneratedUrl(String host, String path) throws IOException {
        // 1. Валидиране и почистване на хоста
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        String cleanedHost = host.trim();

        // Проверка за невалидни символи като интервали в хоста
        if (cleanedHost.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces).");
        }

        // 2. Конструиране на URL
        URL url;
        try {
            // Използваме HTTPS за сигурност; може да се направи конфигурируемо, ако е необходимо
            url = new URL("https", cleanedHost, path);
        } catch (MalformedURLException e) {
            // Тази грешка може да възникне, ако почистеният хост или път все още са невалидни
            throw new IllegalArgumentException("Invalid URL components: " + e.getMessage(), e);
        }

        // 3. Извличане на съдържание
        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Опционално: Задаване на таймаут за свързване и четене
        connection.setConnectTimeout(5000); // 5 секунди
        connection.setReadTimeout(10000);  // 10 секунди

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } catch (IOException e) {
            throw new IOException("Failed to retrieve content from URL: " + url.toString(), e);
        }

        return content.toString();
    }
}
