    /**
     * Obtiene contenido de una URL generada después de validar el host.
     *
     * Esta función sanitiza el host al verificar la presencia de caracteres inválidos como espacios.
     *
     * @param host El nombre del host a validar y usar.
     * @param path La ruta del recurso en el host.
     * @return El contenido de la URL como una cadena de texto.
     * @throws IllegalArgumentException Si el host contiene caracteres inválidos (ej. espacios, nulo o vacío).
     * @throws MalformedURLException Si la URL construida es inválida.
     * @throws IOException Si ocurre un error al abrir la conexión o leer el contenido.
     */
    public String getSanitizedUrlContent(String host, String path) throws MalformedURLException, IOException {
        // 1. Sanitizar el host
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("El host no puede ser nulo o vacío.");
        }
        // Verificar la presencia de caracteres de espacio o control que podrían invalidar el host
        if (host.contains(" ") || host.contains("\t") || host.contains("\n") || host.contains("\r")) {
            throw new IllegalArgumentException("El host contiene caracteres de espacio inválidos.");
