        URL url = new URL("http", host, path);

        // 3. Abrir conexión y leer contenido
        StringBuilder content = new StringBuilder();
        BufferedReader reader = null;
        try {
            URLConnection connection = url.openConnection();
            // Establecer timeouts para evitar esperas indefinidas
            connection.setConnectTimeout(5000); // 5 segundos para establecer la conexión
            connection.setReadTimeout(5000);    // 5 segundos para leer datos

            reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } finally {
            if (reader != null) {
                try {
                    reader.close();
