    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     *
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     *
     * @param host Хост для URL.
     * @param path Путь для URL.
     * @return Содержимое, полученное по URL, в виде строки.
     * @throws IOException Если произошла ошибка ввода-вывода при создании URL или чтении содержимого.
     * @throws IllegalArgumentException Если хост пуст или содержит недопустимые символы после очистки.
     */
    public String getContentFromGeneratedUrl(String host, String path) throws IOException {
        // 1. Очистка хоста: удаление всех пробельных символов
        String cleanedHost = host.replaceAll("\\s+", "");

        // 2. Проверка очищенного хоста
        if (cleanedHost.isEmpty()) {
            throw new IllegalArgumentException("Хост не может быть пустым после очистки.");
        }

        URL url;
        try {
            // 3. Генерация URL с использованием HTTPS для безопасности
            url = new URL("https", cleanedHost, path);
        } catch (MalformedURLException e) {
            // Если хост или путь приводят к неверному формату URL
            throw new IOException("Неверный формат URL: " + e.getMessage(), e);
        }

        // 4. Получение содержимого из URL
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n"); // Добавляем символ новой строки
            }
        }

        // Удаляем последний символ новой строки, если он есть, чтобы избежать лишней пустой строки в конце
        if (content.length() > 0 && content.charAt(content.length() - 1) == '\n') {
            content.deleteCharAt(content.length() - 1);
        }

        return content.toString();
    }
}
