        // 3. Constrói a URL
        // Assumindo o protocolo HTTP. Em um cenário real, o protocolo pode ser um parâmetro.
        String urlString = "http://" + host + effectivePath;

        // 4. Cria e retorna o objeto URL
        return new URL(urlString);
    }
