     * Questa funzione sanifica l'host controllando la presenza di caratteri non validi come gli spazi.
     *
     * @param host L'host da convalidare e utilizzare per costruire l'URL.
     * @param path Il percorso da aggiungere all'host per formare l'URL completo.
     * @return Un oggetto URL valido.
     * @throws MalformedURLException Se l'URL costruito non è valido.
     * @throws IllegalArgumentException Se l'host sanificato è nullo o vuoto.
     */
    public URL retrieveContentFromValidatedHost(String host, String path) throws MalformedURLException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("L'host non può essere nullo o vuoto.");
        }

        // Sanifica l'host rimuovendo caratteri non validi come gli spazi.
        // Una sanificazione più robusta potrebbe includere la rimozione di altri caratteri
        // non consentiti in un hostname o la validazione tramite espressioni regolari.
        String sanitizedHost = host.replaceAll("\\s", ""); // Rimuove tutti gli spazi

        if (sanitizedHost.isEmpty()) {
            throw new IllegalArgumentException("L'host sanificato è vuoto. Controllare i caratteri forniti.");
        }

        // Costruisce l'URL. Si assume un protocollo HTTPS per sicurezza,
        // ma potrebbe essere parametrizzato o dedotto.
        // Assicurati che il path inizi con '/' se non è già così.
        String fullPath = path;
        if (fullPath != null && !fullPath.startsWith("/")) {
            fullPath = "/" + fullPath;
        } else if (fullPath == null) {
            fullPath = "";
        }

        String urlString = "https://" + sanitizedHost + fullPath;

        return new URL(urlString);
    }
}
