     * تقوم هذه الوظيفة بتنظيف المضيف من خلال التحقق من وجود أحرف غير صالحة مثل المسافات.
     *
     * @param host اسم المضيف (مثال: "www.example.com")
     * @param path المسار (مثال: "/api/data")
     * @return محتوى URL كسلسلة نصية
     * @throws IllegalArgumentException إذا كان المضيف غير صالح أو إذا تعذر إنشاء URL
     * @throws IOException إذا حدث خطأ أثناء الاتصال أو قراءة المحتوى
     */
    public String retrieveContentFromValidatedHost(String host, String path) throws IOException {
        // 1. Host Validation and Cleaning
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        String cleanedHost = host.trim(); // Remove leading/trailing spaces

        // Check for invalid characters like spaces within the host
        if (cleanedHost.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces).");
        }
        // Further validation (e.g., regex for domain name format) could be added here
        // For example: if (!cleanedHost.matches("^[a-zA-Z0-9.-]+$")) { ... }

        // Ensure path starts with a '/' if it's not null and not empty
        String finalPath = (path != null && !path.isEmpty() && !path.startsWith("/")) ? "/" + path : (path == null ? "" : path);

        // 2. URL Construction
        URL url;
        try {
            // Using HTTPS for secure communication
            url = new URL("https", cleanedHost, finalPath);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Failed to construct a valid URL with host: " + cleanedHost + " and path: " + finalPath + ". " + e.getMessage(), e);
        }

        // 3. Content Retrieval
        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Set connection timeouts to prevent indefinite waits
            connection.setConnectTimeout(5000); // 5 seconds for connection
            connection.setReadTimeout(10000);  // 10 seconds for reading data

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            throw new IOException("Failed to retrieve content from URL: " + url.toString() + ". " + e.getMessage(), e);
        }

        return content.toString();
    }
}
