        String cleanedHost = cleanAndValidateHost(host);
        if (cleanedHost == null) {
            System.err.println("Σφάλμα: Ο κεντρικός υπολογιστής περιέχει μη έγκυρους χαρακτήρες ή είναι κενός.");
            return null;
        }

        // 2. Δημιουργία της URL
        URL url;
        try {
            // Χρησιμοποιούμε τον καθαρισμένο κεντρικό υπολογιστή
            url = new URL(protocol, cleanedHost, path);
        } catch (MalformedURLException e) {
            System.err.println("Σφάλμα: Μη έγκυρη μορφή URL. " + e.getMessage());
            return null;
        }

        // 3. Ανάκτηση περιεχομένου
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } catch (IOException e) {
            System.err.println("Σφάλμα κατά την ανάγνωση από την URL: " + url.toString() + ". " + e.getMessage());
            return null;
        }

        return content.toString();
    }

