        String cleanedHost = host.replaceAll("\\s+", ""); // Αφαιρεί όλα τα κενά

        // Ελέγχουμε αν ο κεντρικός υπολογιστής είναι κενός μετά τον καθαρισμό
        if (cleanedHost.isEmpty()) {
            return null;
        }

        // Πρόσθετοι έλεγχοι θα μπορούσαν να περιλαμβάνουν:
        // - Έλεγχο για έγκυρη μορφή ονόματος τομέα (π.χ., regex για DNS hostname)
        // - Έλεγχο για IP διεύθυνση
