        String content4 = classX.retrieveContentFromValidatedUrl("ftp", "invalid-host.com", "/");
        if (content4 == null) {
            System.out.println("\nΕπιτυχής χειρισμός μη έγκυρου πρωτοκόλλου (πιθανώς MalformedURLException).");
        }

        // Παράδειγμα με μη έγκυρη διαδρομή (δεν θα προκαλέσει MalformedURLException, αλλά 404 ή άλλο σφάλμα κατά την ανάκτηση)
        String content5 = classX.retrieveContentFromValidatedUrl("https", "www.example.com", "/nonexistent-page-12345.html");
        if (content5 != null) {
            System.out.println("\nΠεριεχόμενο από μη υπάρχουσα σελίδα (πιθανώς HTML για 404):\n" + content5.substring(0, Math.min(content5.length(), 200)) + "...");
