     */
    public Double evaluateMathExpression(String expression) throws IllegalArgumentException {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("表达式不能为空。");
        }

        // 定义不允许的关键词列表，用于防止代码注入或复杂操作
        // 这些关键词通常与系统操作、对象创建、控制流或高级语言特性相关
        List<String> forbiddenKeywords = Arrays.asList(
            "System", "Runtime", "exec", "File", "new", "import", "package", "            ",
            "class", "interface", "while", "for", "if", "else", "try", "catch", "finally",
            "throw", "return", "void", "public", "private", "protected", "static", "final",
            "abstract", "native", "synchronized", "volatile", "transient", "instanceof",
            "this", "super", "null", "true", "false", "function", "var", "let", "const",
            "eval", "window", "document", "process", "require", "module", "global", "console"
        );

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("表达式包含不允许的关键词: " + keyword);
            }
