                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("表达式评估结果不是有效的数字: " + result, e);
                }
            } else {
                throw new IllegalArgumentException("表达式评估结果为空。");
            }
        } catch (ScriptException e) {
            throw new IllegalArgumentException("无法评估数学表达式: " + expression, e);
        } catch (Exception e) {
            // 捕获其他潜在的运行时异常
            throw new IllegalArgumentException("评估表达式时发生意外错误: " + expression, e);
        }
    }
