import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Nagsusuri at nag-evaluate ng isang matematikal na ekspresyon mula sa gumagamit.
     * 
     * Ang function ay nililimitahan ang ekspresyon sa mga pangunahing aritmetika sa pamamagitan ng pag-block ng mga karaniwang mapanganib na keyword.
     *
     * @param expression Ang string na naglalaman ng matematikal na ekspresyon na susuriin.
     * @return Ang resulta ng evaluation bilang isang Double, o null kung may error o hindi valid ang ekspresyon.
     */
    public Double evaluateMathematicalExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return null;
        }

        // Listahan ng mga keyword na ipinagbabawal upang limitahan ang ekspresyon sa simpleng aritmetika.
        // Ito ay isang basic na pagtatangka sa seguridad at hindi kumpleto para sa lahat ng posibleng atake.
        String[] forbiddenKeywords = {
            "System", "Runtime", "ProcessBuilder", "Class", "Object", "java", "javax",
            "import", "new", "eval", "exec", "function", "var", "let", "const",
            "while", "for", "if", "else", "try", "catch", "throw", "return",
            "delete", "void", "this", "window", "document", "console", "alert",
            "script", "<", ">", "&", "|", "^", "~", "!", "?", ":", ";",
            "\\", "`", "$", "#", "@", "%", "{", "}", "[", "]",
            "Math.pow", "Math.sqrt", "Math.sin", "Math.cos", "Math.tan", // Maaaring payagan ang Math functions kung ninanais
            "\\b[a-zA-Z_][a-zA-Z0-9_]*\\s*\\(" // Basic pattern to block function calls
        };

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : forbiddenKeywords) {
            // Gumagamit ng regex para sa mas tumpak na paghahanap ng mga keyword, lalo na para sa function calls.
            // Ang "\\b" ay para sa word boundary upang maiwasan ang partial matches (e.g., "system" sa "subsystem").
            // Para sa Math functions at generic function calls, kailangan ng mas sopistikadong regex.
            if (keyword.contains("Math.") || keyword.contains("\\b[a-zA-Z_]")) {
                if (lowerCaseExpression.matches(".*" + keyword + ".*")) {
                    System.err.println("Error: Expression contains forbidden pattern: " + keyword);
                    return null;
                }
            } else if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                System.err.println("Error: Expression contains forbidden keyword: " + keyword);
                return null;
            }
        }

        // Regular expression to check if the expression contains only allowed characters
        // Allowed: digits, +, -, *, /, ., and spaces.
        // This is a crucial step to prevent injection of non-arithmetic characters.
        if (!expression.matches("^[0-9+\\-*/.()\\s]+$")) {
            System.err.println("Error: Expression contains disallowed characters.");
            return null;
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // O "Nashorn" para sa mas lumang Java

        if (engine == null) {
            System.err.println("Error: JavaScript engine not found. Ensure you are using a JDK that includes it.");
            return null;
        }

        try {
            Object result = engine.eval(expression);
            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                System.err.println("Error: Evaluation did not return a number. Result type: " + result.getClass().getName());
                return null;
            }
        } catch (ScriptException e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
            return null;
        } catch (Exception e) {
            System.err.println("An unexpected error occurred: " + e.getMessage());
            return null;
        }
    }

    // Maaaring magdagdag ng main method para sa testing
    public static void main(String[] args) {
