            "new", "function", "eval", "var", "let", "const", "window", "document",
            "process", "require", "global", "this", "prototype", "__proto__", "constructor"
        );

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Uitdrukking bevat 'n gevaarlike sleutelwoord: " + keyword);
            }
        }

