import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Menganalisis dan mengevaluasi ekspresi matematika dari pengguna.
     * 
     * Fungsi ini membatasi ekspresi pada aritmatika dasar dengan memblokir
     * kata kunci berbahaya yang umum.
     * 
     * @param expression Ekspresi matematika yang akan dievaluasi.
     * @return Hasil evaluasi ekspresi atau pesan kesalahan jika terjadi masalah.
     */
    public String evaluateExpression(String expression) {
        // Daftar kata kunci berbahaya yang akan diblokir
        String[] dangerousKeywords = {
            "import", "java", "runtime", "exec", "file", "system", "processbuilder",
            "class", "new", "thread", "while", "for", "if", "else", "try", "catch",
            "finally", "return", "void", "public", "private", "protected", "static",
            "final", "abstract", "interface", "enum", "extends", "implements", "throws",
            "package", "break", "continue", "switch", "case", "default", "do",
            "instanceof", "super", "this", "synchronized", "volatile", "transient",
            "assert", "goto", "const", "strictfp", "native", "null", "true", "false",
            "function", "var", "let", "const", "eval", "window", "document", "console"
        };

        // Normalisasi ekspresi untuk pemeriksaan (misal: ubah ke huruf kecil)
        String lowerCaseExpression = expression.toLowerCase();

        // Periksa apakah ekspresi mengandung kata kunci berbahaya
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                return "Error: Ekspresi mengandung kata kunci yang tidak diizinkan: '" + keyword + "'";
            }
        }

        // Inisialisasi ScriptEngineManager
        ScriptEngineManager manager = new ScriptEngineManager();
