        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            return "Error: Mesin JavaScript tidak ditemukan. Pastikan JRE Anda mendukung JavaScript.";
        }

        try {
            // Evaluasi ekspresi
            Object result = engine.eval(expression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            // Tangani kesalahan sintaksis atau runtime dari ekspresi
            return "Error: Kesalahan dalam ekspresi matematika: " + e.getMessage();
        } catch (Exception e) {
            // Tangani kesalahan umum lainnya
            return "Error: Terjadi kesalahan tak terduga: " + e.getMessage();
        }
    }

    // Metode main untuk pengujian (opsional, bisa dihapus jika tidak diperlukan)
