        System.out.println("Math.pow(2, 3) = " + evaluator.evaluateExpression("Math.pow(2, 3)")); // Output: 8.0
        System.out.println("10 / 0 = " + evaluator.evaluateExpression("10 / 0")); // Output: Infinity
