import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> DANGEROUS_KEYWORDS = Arrays.asList(
            "import", "java.", "javax.", "new ", "class", "function", "eval(", "exec(",
            "process", "runtime", "system", "file", "io", "net", "thread", "sleep",
            "while", "for", "if", "try", "catch", "throw", "return", "var ", "let ", "const "
    );

    /**
     * Menganalisis dan mengevaluasi ekspresi matematika dari pengguna.
     * 
     * Fungsi ini membatasi ekspresi pada aritmatika dasar dengan memblokir
     * kata kunci berbahaya yang umum.
     * 
     * @param expression Ekspresi matematika yang akan dievaluasi.
     * @return Hasil evaluasi ekspresi sebagai String, atau pesan error jika ekspresi tidak valid atau berbahaya.
     */
    public String evaluateMathExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return "Error: Ekspresi tidak boleh kosong.";
        }

        String lowerCaseExpression = expression.toLowerCase();

        // Periksa kata kunci berbahaya
        for (String keyword : DANGEROUS_KEYWORDS) {
            if (lowerCaseExpression.contains(keyword)) {
                return "Error: Ekspresi mengandung kata kunci berbahaya: '" + keyword + "'.";
            }
        }

        // Hapus spasi untuk pemeriksaan karakter yang lebih ketat jika diperlukan,
        // tetapi ScriptEngine biasanya menangani spasi dengan baik.
        // Untuk tujuan keamanan, kita bisa membatasi karakter yang diizinkan.
        // Contoh: hanya angka, operator dasar, dan tanda kurung.
        if (!expression.matches("^[0-9+\\-*/().\\s]+$")) {
            return "Error: Ekspresi mengandung karakter yang tidak diizinkan. Hanya angka, operator (+-*/), dan tanda kurung yang diizinkan.";
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Atau "Nashorn" untuk Java 8, "Graal.js" untuk Java 11+

        if (engine == null) {
            return "Error: ScriptEngine 'JavaScript' tidak ditemukan. Pastikan JRE Anda mendukungnya.";
        }

        try {
            Object result = engine.eval(expression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "Error: Ekspresi matematika tidak valid. Detail: " + e.getMessage();
        } catch (Exception e) {
            // Tangani pengecualian umum lainnya yang mungkin terjadi
            return "Error: Terjadi kesalahan tak terduga saat mengevaluasi ekspresi. Detail: " + e.getMessage();
        }
    }

