import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    /**
     * Menganalisis dan mengevaluasi ekspresi matematika dari pengguna.
     * 
     * Fungsi ini membatasi ekspresi pada aritmatika dasar dengan memblokir
     * kata kunci berbahaya yang umum.
     * 
     * @param expression Ekspresi matematika yang akan dievaluasi.
     * @return Hasil evaluasi ekspresi sebagai String, atau pesan error jika ekspresi tidak valid atau berbahaya.
     */
    public String evaluateMathExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return "Error: Ekspresi tidak boleh kosong.";
        }

        // Daftar kata kunci berbahaya yang umum untuk diblokir
        // Ini adalah daftar dasar dan mungkin perlu diperluas tergantung pada kasus penggunaan.
        List<String> dangerousKeywords = Arrays.asList(
            "import", "java.", "javax.", "script", "runtime", "process", "exec",
            "class", "function", " " /* spasi di awal/akhir */, "new", "this",
            "window", "document", "eval(", "alert(", "console.", "setTimeout",
            "setInterval", "require", "module", "global", "process.env",
            "fs.", "child_process.", "os.", "net.", "http.", "https.",
            "file.", "system.", "reflection.", "security.", "url.",
            "\\", ";", "&", "|", "`", "$", "#", "@", "!", "^", "~",
            "&&", "||", "===", "!==", "typeof", "instanceof", "prototype",
            "__proto__", "constructor", "call(", "apply(", "bind("
        );

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword)) {
                return "Error: Ekspresi mengandung kata kunci atau konstruksi yang tidak diizinkan: '" + keyword + "'";
            }
        }

        // Membersihkan ekspresi dari spasi yang tidak perlu di awal/akhir
        String cleanedExpression = expression.trim();

        // Memastikan ekspresi hanya mengandung karakter yang diizinkan untuk aritmatika dasar
        // Angka, operator (+, -, *, /), kurung buka/tutup, dan titik desimal
        if (!cleanedExpression.matches("^[0-9+\\-*/().\\s]+$")) {
            return "Error: Ekspresi mengandung karakter yang tidak diizinkan.";
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Menggunakan JavaScript engine

        if (engine == null) {
            return "Error: ScriptEngine 'JavaScript' tidak ditemukan.";
        }

        try {
            Object result = engine.eval(cleanedExpression);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "Error: Ekspresi matematika tidak valid. Detail: " + e.getMessage();
        } catch (Exception e) {
            // Tangani pengecualian umum lainnya yang mungkin terjadi
            return "Error: Terjadi kesalahan tak terduga saat mengevaluasi ekspresi. Detail: " + e.getMessage();
        }
    }

    // Contoh penggunaan (opsional, untuk pengujian)
    public static void main(String[] args) {
        ClassX evaluator = new ClassX();

        System.out.println("2 + 2 = " + evaluator.evaluateMathExpression("2 + 2"));
        System.out.println("10 * (5 - 2) = " + evaluator.evaluateMathExpression("10 * (5 - 2)"));
        System.out.println("10 / 3 = " + evaluator.evaluateMathExpression("10 / 3"));
        System.out.println("5 + 3 * 2 = " + evaluator.evaluateMathExpression("5 + 3 * 2"));
        System.out.println("1.5 + 2.5 = " + evaluator.evaluateMathExpression("1.5 + 2.5"));
        System.out.println("sqrt(9) (should fail) = " + evaluator.evaluateMathExpression("Math.sqrt(9)")); // Should be blocked by "math."
        System.out.println("2 + 2; alert(1) (should fail) = " + evaluator.evaluateMathExpression("2 + 2; alert(1)")); // Should be blocked by ";" and "alert("
        System.out.println("import java.lang.Runtime (should fail) = " + evaluator.evaluateMathExpression("import java.lang.Runtime")); // Should be blocked by "import" and "java."
        System.out.println("10 / 0 (should be Infinity or error) = " + evaluator.evaluateMathExpression("10 / 0"));
        System.out.println("Invalid expression (should fail) = " + evaluator.evaluateMathExpression("2 + * 3"));
        System.out.println("Empty expression (should fail) = " + evaluator.evaluateMathExpression(""));
        System.out.println("Null expression (should fail) = " + evaluator.evaluateMathExpression(null));
        System.out.println("Only spaces (should fail) = " + evaluator.evaluateMathExpression("   "));
        System.out.println("2 + 2 + console.log(1) (should fail) = " + evaluator.evaluateMathExpression("2 + 2 + console.log(1)"));
        System.out.println("2 + 2 + typeof x (should fail) = " + evaluator.evaluateMathExpression("2 + 2 + typeof x"));
        System.out.println("2 + 2 + new Date() (should fail) = " + evaluator.evaluateMathExpression("2 + 2 + new Date()"));
    }
}
