    /**
     * Elemzi és értékeli a felhasználótól származó matematikai kifejezést.
     * <p>
     * A függvény korlátozza a kifejezést az alapvető aritmetikára azáltal, hogy blokkolja a
     * gyakori veszélyes kulcsszavakat.
     *
     * @param expression A kiértékelendő matematikai kifejezés.
     * @return A kifejezés eredménye, vagy null, ha hiba történt vagy a kifejezés érvénytelen.
     */
    public Double evaluateMathExpression(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            return null;
        }

        // Veszélyes kulcsszavak listája
        String[] dangerousKeywords = {
            "System", "Runtime", "ProcessBuilder", "File", "Class", "Object",
            "Thread", "exec", "eval", "import", "java", "javax", "net", "io",
            "reflect", "script", "nashorn", "rhino", "function", "var", "let",
            "const", "new", "this", " " // Space is included to prevent complex expressions like "1 + 1" being blocked by " "
        };

        // Ellenőrizzük a kifejezést veszélyes kulcsszavakra
        String lowerCaseExpression = expression.toLowerCase();
        for (String keyword : dangerousKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                // Logolhatnánk vagy kivételt dobhatnánk itt
                System.err.println("A kifejezés veszélyes kulcsszót tartalmaz: " + keyword);
                return null; // Visszaadunk null-t, ha veszélyes kulcsszót találunk
            }
        }

        // Engedélyezett karakterek (számok, alapvető operátorok, zárójelek)
        // Ez egy kiegészítő biztonsági réteg, ami csak a megengedett karaktereket engedi át.
        // A regex a következőket engedélyezi: számjegyek (0-9), pont (.), alapvető aritmetikai operátorok (+-*/), zárójelek (()).
        if (!expression.matches("^[0-9+\\-*/().\\s]+$")) {
            System.err.println("A kifejezés érvénytelen karaktereket tartalmaz.");
            return null;
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Vagy "Graal.js" ha elérhető

        if (engine == null) {
            System.err.println("JavaScript motor nem található. Győződjön meg róla, hogy a JDK tartalmazza.");
            return null;
        }

        try {
            // A ScriptEngine alapértelmezés szerint képes JavaScript kód futtatására.
            // A fenti kulcsszó-ellenőrzés és regex szűrés célja, hogy minimalizálja a kockázatot.
            Object result = engine.eval(expression);

            if (result instanceof Number) {
                return ((Number) result).doubleValue();
            } else {
                System.err.println("A kifejezés eredménye nem szám: " + result);
                return null;
            }
        } catch (ScriptException e) {
            System.err.println("Hiba történt a kifejezés kiértékelése során: " + e.getMessage());
            return null;
        } catch (Exception e) {
            System.err.println("Váratlan hiba történt: " + e.getMessage());
            return null;
        }
    }

    // Példa használatra
    public static void main(String[] args) {
        ClassX calculator = new ClassX();

        // Érvényes kifejezések
        System.out.println("1 + 1 = " + calculator.evaluateMathExpression("1 + 1")); // 2.0
        System.out.println("2 * (3 + 4) = " + calculator.evaluateMathExpression("2 * (3 + 4)")); // 14.0
        System.out.println("10 / 3 = " + calculator.evaluateMathExpression("10 / 3")); // 3.333...
        System.out.println("5 - 2.5 = " + calculator.evaluateMathExpression("5 - 2.5")); // 2.5
        System.out.println("((1 + 2) * 3) / 4 = " + calculator.evaluateMathExpression("((1 + 2) * 3) / 4")); // 2.25

        // Veszélyes kulcsszavakat tartalmazó kifejezések
        System.out.println("System.exit(0) = " + calculator.evaluateMathExpression("System.exit(0)")); // null
        System.out.println("new Date() = " + calculator.evaluateMathExpression("new Date()")); // null
        System.out.println("1 + eval('2') = " + calculator.evaluateMathExpression("1 + eval('2')")); // null
        System.out.println("java.lang.Math.PI = " + calculator.evaluateMathExpression("java.lang.Math.PI")); // null
        System.out.println("var x = 1; x + 2 = " + calculator.evaluateMathExpression("var x = 1; x + 2")); // null

        // Érvénytelen karaktereket tartalmazó kifejezések
        System.out.println("1 ^ 2 = " + calculator.evaluateMathExpression("1 ^ 2")); // null (hatványozás nem engedélyezett)
        System.out.println("1 % 2 = " + calculator.evaluateMathExpression("1 % 2")); // null (moduló nem engedélyezett)
        System.out.println("1 + a = " + calculator.evaluateMathExpression("1 + a")); // null

        // Üres vagy null kifejezések
        System.out.println("null expression = " + calculator.evaluateMathExpression(null)); // null
        System.out.println("empty expression = " + calculator.evaluateMathExpression("")); // null
        System.out.println("blank expression = " + calculator.evaluateMathExpression("   ")); // null
    }
}
