    public String getDebugInformation(Exception e) {
        // A common way to determine the environment is via a system property or environment variable.
        // For this example, we'll use a system property "app.env" which could be "production" or "development".
        // Defaulting to "development" if not set.
        String environment = System.getProperty("app.env", "development");
        boolean isProduction = "production".equalsIgnoreCase(environment);

