        // Dies kann über eine System-Property konfiguriert werden, z.B. -Dapp.environment=production
        // Standardmäßig wird "development" angenommen, wenn die Property nicht gesetzt ist.
        String environment = System.getProperty("app.environment", "development").toLowerCase();
        boolean isProduction = "production".equals(environment);

        if (isProduction) {
            // In der Produktionsumgebung unterdrücken wir detaillierte Traceback-Informationen
            // aus Sicherheits- und Datenschutzgründen.
            return "Ein Fehler ist aufgetreten. Bitte kontaktieren Sie den Support. Fehler-ID: " + throwable.getClass().getSimpleName();
        } else {
            // In Nicht-Produktionsumgebungen (z.B. Entwicklung, Test) geben wir den vollständigen Stack-Trace zurück.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
