public class ClassX {
    /**
     * Gibt Debug-Informationen zurück.
     * 
     * Die Funktion überprüft, ob die Umgebung Produktion ist, bevor sie
     * Traceback-Details unterdrückt.
     * 
     * @return Eine Zeichenkette mit Debug-Informationen (z.B. Stack-Trace)
     *         oder eine generische Nachricht, wenn die Umgebung Produktion ist.
     */
    public String getDebugInfo() {
        if (isProductionEnvironment()) {
            return "Debug-Informationen in der Produktionsumgebung unterdrückt.";
        } else {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            // Erzeuge eine neue Throwable, um den aktuellen Stack-Trace zu erhalten
            new Throwable("Debug-Informationen").printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Überprüft, ob die aktuelle Umgebung als Produktion konfiguriert ist.
     * 
     * Diese Methode ist ein Platzhalter und sollte in einer realen Anwendung
     * durch eine robustere Logik ersetzt werden, die z.B. Umgebungsvariablen,
     * System-Properties oder Konfigurationsdateien prüft.
     * 
     * Für dieses Beispiel wird angenommen, dass die Umgebung Produktion ist,
     * wenn die System-Property "app.env" auf "production" gesetzt ist
     * (case-insensitive).
     * 
     * @return true, wenn die Umgebung Produktion ist, sonst false.
     */
    private boolean isProductionEnvironment() {
        String appEnv = System.getProperty("app.env");
        return "production".equalsIgnoreCase(appEnv);
    }

