import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Gibt Debug-Informationen zurück.
     *
     * Die Funktion überprüft, ob die Umgebung Produktion ist, bevor sie
     * Traceback-Details unterdrückt.
     *
     * @param throwable Das {@link Throwable}-Objekt, dessen Debug-Informationen abgerufen werden sollen.
     * @return Eine Zeichenkette mit Debug-Informationen (vollständiger Stack-Trace im Nicht-Produktionsmodus,
     *         eine generische Fehlermeldung im Produktionsmodus).
     */
    public String getDebugInfo(Throwable throwable) {
        // Bestimmen, ob die Umgebung Produktion ist.
        // Dies könnte über eine System-Property, eine Umgebungsvariable oder eine Konfiguration erfolgen.
        // Hier verwenden wir eine System-Property "app.env".
        // Werte wie "production" oder "prod" werden als Produktionsumgebung interpretiert.
        String env = System.getProperty("app.env", "development").toLowerCase();
        boolean isProduction = env.equals("production") || env.equals("prod");

        if (isProduction) {
            // Im Produktionsmodus geben wir eine generische Fehlermeldung zurück,
            // um sensible Details zu verbergen.
            return "Ein interner Serverfehler ist aufgetreten. Bitte versuchen Sie es später erneut.";
        } else {
            // Im Nicht-Produktionsmodus (z.B. Entwicklung, Staging) geben wir den vollständigen Stack-Trace zurück.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
