import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Hata ayıklama bilgilerini döndürür.
     * 
     * Fonksiyon, traceback detaylarını bastırmadan önce ortamın üretim olup olmadığını kontrol eder.
     *
     * @param t Hata ayıklama bilgileri alınacak Throwable nesnesi.
     * @return Hata ayıklama bilgilerini içeren bir String.
     */
    public String getDebugInfo(Throwable t) {
        StringBuilder debugInfo = new StringBuilder();

        debugInfo.append("Error Type: ").append(t.getClass().getName()).append("\n");
        debugInfo.append("Error Message: ").append(t.getMessage()).append("\n");

        // Check if the environment is production.
        // This can be determined by a system property, an environment variable, or a configuration setting.
        // For this example, we'll use a system property named "env".
        // If "env" is "production" (case-insensitive), traceback details will be suppressed.
        String environment = System.getProperty("env", "development"); // Default to "development" if not set

        if ("production".equalsIgnoreCase(environment)) {
            debugInfo.append("Traceback details are suppressed in the production environment.");
        } else {
            // If not production, append the full stack trace.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            debugInfo.append("Stack Trace:\n").append(sw.toString());
        }

        return debugInfo.toString();
    }
}
