     * Si el entorno es de producción (determinado por la propiedad del sistema "env" siendo "prod"),
     * se devuelve un mensaje genérico. De lo contrario, se proporciona el seguimiento de pila completo.
     *
     * @param throwable La excepción para la cual se generará la información de depuración.
     * @return Una cadena que contiene la información de depuración o un mensaje genérico si es producción.
     */
    public static String getDebugInformation(Throwable throwable) {
        // Determina si el entorno es de producción.
        // Se asume que la propiedad del sistema "env" puede ser "prod" para producción.
        // Por defecto, si no se establece o es diferente, se considera un entorno de desarrollo/no producción.
        boolean isProduction = "prod".equalsIgnoreCase(System.getProperty("env", "dev"));

        if (isProduction) {
            // En producción, suprimir detalles sensibles del seguimiento de pila.
            // Devolver un mensaje genérico o solo el tipo de excepción.
            return "An unexpected error occurred. Please contact support. Error type: " + throwable.getClass().getSimpleName();
        } else {
            // En entornos que no son de producción, proporcionar el seguimiento de pila completo.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
