            // Sa non-production (hal. development, testing), ibalik ang buong stack trace.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Sinusuri kung ang kasalukuyang kapaligiran ay production.
     * Maaaring i-configure ito sa pamamagitan ng system property, environment variable, o configuration file.
     *
     * @return true kung ang kapaligiran ay production, false kung hindi.
     */
    private static boolean isProductionEnvironment() {
        // Halimbawa: Suriin ang isang system property na "app.env"
        // Maaari itong itakda sa pamamagitan ng -Dapp.env=production kapag pinapatakbo ang JVM.
        String env = System.getProperty("app.env");
        return "production".equalsIgnoreCase(env) || "prod".equalsIgnoreCase(env);
    }
}
