    // Define a constant for the system property key that indicates the environment
    private static final String ENVIRONMENT_PROPERTY_KEY = "app.environment";
    // Define the value that signifies a production environment
    private static final String PRODUCTION_ENVIRONMENT_VALUE = "production";

    /**
     * Palauttaa virheenkorjaustietoja.
