     *         eikä ole tuotantoympäristössä.
     */
    public static String getDebugInformation(Throwable throwable) {
        // Tarkista, onko ympäristö tuotantovaiheessa
        String currentEnvironment = System.getProperty(ENVIRONMENT_PROPERTY_KEY);
        boolean isProduction = PRODUCTION_ENVIRONMENT_VALUE.equalsIgnoreCase(currentEnvironment);

        if (isProduction) {
            // Tuotantoympäristössä palauta yleinen virheilmoitus
