import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Renvoie des informations de débogage.
     *
     * La fonction vérifie si l'environnement est en production avant de supprimer les détails de la trace.
     *
     * @return Une chaîne de caractères contenant les informations de débogage.
     */
    public String getDebugInfo() {
        // Détermine si l'environnement est en production.
        // Ceci peut être basé sur une propriété système, une variable d'environnement,
        // ou une configuration d'application.
        // Pour cet exemple, nous utilisons une propriété système "env.production".
        boolean isProduction = Boolean.parseBoolean(System.getProperty("env.production", "false"));

        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        try {
            // Simule une situation où une trace de pile pourrait être générée,
            // par exemple, une exception.
            throw new RuntimeException("Événement de débogage simulé ou erreur.");
        } catch (Exception e) {
            if (isProduction) {
                // En production, fournir un message général sans détails de la trace de pile.
                pw.println("Une erreur est survenue. Veuillez contacter le support avec l'ID de référence : " + System.currentTimeMillis());
                pw.println("Type d'erreur : " + e.getClass().getSimpleName());
                pw.println("Message d'erreur : " + e.getMessage());
                // Les détails complets de la trace pourraient être loggés en interne
                // sans être exposés à l'utilisateur final.
            } else {
                // Dans les environnements hors production (développement, test),
                // fournir la trace de pile complète pour faciliter le débogage.
                pw.println("--- INFORMATIONS DE DÉBOGAGE ---");
                pw.println("Environnement : DÉVELOPPEMENT/TEST");
                pw.println("Horodatage : " + new java.util.Date());
                pw.println("Trace de pile complète :");
                e.printStackTrace(pw); // Imprime la trace de pile dans le StringWriter
                pw.println("--- FIN DES INFORMATIONS DE DÉBOGAGE ---");
            }
        } finally {
            pw.close();
        }

        return sw.toString();
    }
}
