public class ClassX {

    private static final String PRODUCTION_ENV_PROPERTY = "app.env";
    private static final String PRODUCTION_ENV_VALUE = "production";

    /**
     * Επιστρέφει πληροφορίες αποσφαλμάτωσης.
     * 
     * Η συνάρτηση ελέγχει αν το περιβάλλον είναι παραγωγής πριν αποκρύψει τις λεπτομέρειες της ιχνιλάτησης.
     *
     * @param throwable Το αντικείμενο Throwable από το οποίο θα εξαχθούν οι πληροφορίες αποσφαλμάτωσης.
     * @return Μια συμβολοσειρά που περιέχει πληροφορίες αποσφαλμάτωσης. Εάν το περιβάλλον είναι παραγωγής,
     *         επιστρέφεται ένα γενικό μήνυμα σφάλματος. Διαφορετικά, επιστρέφεται η πλήρης ιχνιλάτηση.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (isProductionEnvironment()) {
            return "An unexpected error occurred. Please try again later.";
        } else {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Ελέγχει αν το τρέχον περιβάλλον εκτέλεσης είναι παραγωγής.
     * Αυτό καθορίζεται από την ιδιότητα συστήματος "app.env" που έχει οριστεί σε "production".
     *
     * @return true αν το περιβάλλον είναι παραγωγής, false διαφορετικά.
     */
    private static boolean isProductionEnvironment() {
        String env = System.getProperty(PRODUCTION_ENV_PROPERTY);
        return PRODUCTION_ENV_VALUE.equalsIgnoreCase(env);
    }

    // Example usage (optional, for demonstration)
    public static void main(String[] args) {
        try {
            int result = 10 / 0; // This will cause an ArithmeticException
        } catch (Exception e) {
            System.out.println("--- Debug Info (Default/Non-Production) ---");
            System.out.println(ClassX.getDebugInfo(e));

            System.setProperty(PRODUCTION_ENV_PROPERTY, PRODUCTION_ENV_VALUE);
            System.out.println("\n--- Debug Info (Production Environment) ---");
            System.out.println(ClassX.getDebugInfo(e));

            System.clearProperty(PRODUCTION_ENV_PROPERTY); // Clean up
        }
    }
}
