public class ClassX {
    /**
     * Bereinigt Benutzereingaben, indem Skript-Tags entfernt werden.
     * 
     * Die Funktion verwendet String-Ersetzung, um <script>-Tags zu entfernen.
     *
     * @param input Die zu bereinigende Benutzereingabe.
     * @return Die bereinigte Eingabe ohne Skript-Tags.
     */
    public String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Entfernt öffnende <script...> Tags (Groß-/Kleinschreibung ignorieren)
        // Der Regex `.*?` ist nicht-gierig und passt bis zum ersten '>'
        String sanitizedInput = input.replaceAll("(?i)<script.*?>", "");

        // Entfernt schließende </script> Tags (Groß-/Kleinschreibung ignorieren)
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
    }
}
