public class ClassX {
    /**
     * Membersihkan input pengguna dengan menghapus tag skrip.
     *
     * Fungsi ini menggunakan penggantian string untuk menghapus tag &lt;script&gt;.
     * Ini akan menghapus seluruh blok skrip, termasuk tag pembuka, tag penutup, dan konten di antaranya.
     * Penggantian dilakukan secara case-insensitive dan juga menangani tag skrip yang mungkin memiliki atribut.
     *
     * @param userInput String input pengguna yang mungkin berisi tag skrip.
     * @return String input yang telah dibersihkan dari tag skrip.
     */
    public String sanitizeInput(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        String sanitizedInput = userInput;

        // Langkah 1: Hapus seluruh blok <script>...</script> secara case-insensitive.
        // Regex ini mencocokkan tag <script> pembuka (dengan atribut opsional),
        // konten di dalamnya (non-greedy), dan tag </script> penutup.
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script\\b[^>]*>(.*?)</script>", "");

        // Langkah 2: Hapus tag <script> pembuka yang mungkin tersisa (misalnya, tanpa tag penutup).
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script\\b[^>]*>", "");

        // Langkah 3: Hapus tag </script> penutup yang mungkin tersisa (misalnya, tanpa tag pembuka).
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
    }
}
