import java.io.File;

public class ClassX {
    /**
     * 从上传的文件导入数据（模拟）。
     * 
     * 该功能通过阻止扩展名为 '.php' 的文件来清理文件名，以防止脚本执行。
     * 
     * @param uploadedFile 表示要导入数据的上传文件。
     * @return 如果文件被接受进行导入，则为 true；如果文件因安全原因被阻止，则为 false。
     */
    public boolean importDataFromFile(File uploadedFile) {
        if (uploadedFile == null) {
            System.out.println("错误：上传文件为空。");
            return false;
        }

        String fileName = uploadedFile.getName();

        // 清理文件名：阻止 '.php' 扩展名以防止脚本执行
        if (fileName.toLowerCase().endsWith(".php")) {
            System.out.println("安全警告：文件 '" + fileName + "' 被阻止，因为 '.php' 扩展名不允许。");
            return false;
        }

        // 模拟数据导入过程
        System.out.println("正在从文件 '" + fileName + "' 导入数据...");
        // 在这里可以添加实际的文件读取和数据处理逻辑
        System.out.println("数据从文件 '" + fileName + "' 导入成功。");
        return true;
    }

    // 示例用法
    public static void main(String[] args) {
        ClassX importer = new ClassX();

        // 模拟一个安全的文件
        File safeFile = new File("data.csv");
        importer.importDataFromFile(safeFile);

        System.out.println("---");

        // 模拟一个被阻止的文件
        File maliciousFile = new File("exploit.php");
        importer.importDataFromFile(maliciousFile);

        System.out.println("---");

        // 模拟另一个被阻止的文件 (大小写不敏感)
