import java.io.File;

public class ClassX {
    /**
     * Yüklenen bir dosyadan veri alır (Simüle Edilmiş).
     *
     * Fonksiyon, '.php' uzantısına sahip dosyaları engelleyerek dosya adını temizler ve böylece betik çalıştırılmasını önler.
     *
     * @param file Veri alınacak dosya.
     * @return Dosyadan alınan simüle edilmiş veri.
     * @throws IllegalArgumentException Eğer dosya adı '.php' uzantısına sahipse veya dosya null ise.
     */
    public String getDataFromFile(File file) {
        if (file == null) {
            throw new IllegalArgumentException("Dosya null olamaz.");
        }

        String fileName = file.getName();

        // '.php' uzantısını (büyük/küçük harf duyarsız) kontrol et
        if (fileName.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("'.php' uzantılı dosyaların işlenmesine izin verilmez: " + fileName);
