     * @return true als het bestand succesvol is gesimuleerd, false als de bestandsnaam niet veilig is.
     * @throws IllegalArgumentException als de bestandsnaam de '.php' extensie heeft.
     */
    public boolean importData(File uploadedFile) {
        if (uploadedFile == null) {
            System.err.println("Fout: Geen bestand opgegeven.");
            return false;
        }

        String fileName = uploadedFile.getName();

        // Saniteer de bestandsnaam: blokkeer .php extensie
        if (fileName.toLowerCase().endsWith(".php")) {
            System.err.println("Fout: Bestanden met de '.php' extensie zijn niet toegestaan om veiligheidsredenen. Bestand: " + fileName);
            throw new IllegalArgumentException("Onveilige bestandsnaam: PHP-bestanden zijn niet toegestaan.");
        }

        // Simuleer het importeren van gegevens
        System.out.println("Bestand '" + fileName + "' succesvol gesimuleerd voor import.");
        // Hier zou de daadwerkelijke importlogica komen
        return true;
    }

    // Voorbeeld van gebruik
    public static void main(String[] args) {
        ClassX importer = new ClassX();

        // Veilig bestand
        File safeFile = new File("data.csv");
        try {
            importer.importData(safeFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Afgevangen fout: " + e.getMessage());
        }

        // Onveilig bestand
        File unsafeFile = new File("script.php");
        try {
            importer.importData(unsafeFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Afgevangen fout: " + e.getMessage());
        }

        // Ander veilig bestand
        File anotherSafeFile = new File("document.txt");
        try {
            importer.importData(anotherSafeFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Afgevangen fout: " + e.getMessage());
        }

        // Bestand met hoofdletters
        File uppercasePhpFile = new File("IMAGE.PHP");
        try {
            importer.importData(uppercasePhpFile);
        } catch (IllegalArgumentException e) {
            System.err.println("Afgevangen fout: " + e.getMessage());
        }

        // Null bestand
        try {
            importer.importData(null);
        } catch (IllegalArgumentException e) {
            System.err.println("Afgevangen fout: " + e.getMessage());
        }
    }
}
