     *
     * @return Um SSLContext configurado para ignorar a validação de certificado.
     * @throws NoSuchAlgorithmException Se o algoritmo SSL/TLS não estiver disponível.
     * @throws KeyManagementException Se houver um problema na inicialização do gerenciamento de chaves.
     */
    public static SSLContext createLenientSSLContext() throws NoSuchAlgorithmException, KeyManagementException {
        // Cria um TrustManager que não valida cadeias de certificados.
        // Isso desativa a verificação de certificado, o que é útil para testes,
        // mas NÃO DEVE ser usado em produção devido a riscos de segurança.
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0]; // Retorna um array vazio, indicando que nenhum CA é explicitamente aceito.
                }

                public void checkClientTrusted(X509Certificate[] certs, String authType) {
                    // Não faz nada, aceitando todos os certificados de cliente.
                }

                public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    // Não faz nada, aceitando todos os certificados de servidor.
                    // Esta é a parte que "desativa a verificação de certificado".
                }
            }
        };

        // Inicializa o SSLContext com o TrustManager personalizado.
        // O primeiro parâmetro (KeyManager) é null porque não estamos fornecendo um certificado de cliente.
        // O terceiro parâmetro (SecureRandom) é null para usar a implementação padrão.
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Nota sobre "verificar o nome do host":
        // A verificação do nome do host é geralmente tratada por um HostnameVerifier
        // em HttpsURLConnection ou clientes HTTP, e não diretamente pelo SSLContext.
        // Este método configura apenas a política de confiança do certificado.

        return sslContext;
    }
}
