    /**
     * Valide le format d'un en-tête HTTP.
     * L'en-tête est considéré valide s'il n'est pas nul, non vide et contient uniquement
     * des caractères alphanumériques (a-z, A-Z, 0-9) et des espaces.
     *
     * @param httpHeader La chaîne de caractères représentant l'en-tête HTTP à valider.
     * @return {@code true} si l'en-tête est valide selon les critères spécifiés, {@code false} sinon.
     */
    public boolean isValidHttpHeader(String httpHeader) {
        // Un en-tête nul ou vide n'est pas valide.
        if (httpHeader == null || httpHeader.isEmpty()) {
            return false;
        }

        // Expression régulière pour valider que l'en-tête contient uniquement
        // des caractères alphanumériques et des espaces.
