        // [a-zA-Z0-9 ] : correspond à une lettre (majuscule ou minuscule), un chiffre ou un espace
        // + : un ou plusieurs des caractères précédents
        // $ : fin de la chaîne
        String regex = "^[a-zA-Z0-9 ]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(httpHeader);

        return matcher.matches();
    }
}
