import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analyse un en-tête HTTP.
     * 
     * La fonction valide le format de l'en-tête en utilisant une expression régulière pour s'assurer qu'il ne contient que des caractères alphanumériques et des espaces.
     *
     * @param header La chaîne de caractères représentant l'en-tête HTTP à valider.
     * @return {@code true} si l'en-tête est valide (contient uniquement des caractères alphanumériques et des espaces), {@code false} sinon.
     */
    public boolean isValidHttpHeader(String header) {
        if (header == null) {
            return false;
        }

        // Regex to ensure the header contains only alphanumeric characters and spaces
        // ^    - start of the string
        // [a-zA-Z0-9 ] - matches any uppercase letter, lowercase letter, digit, or space
        // +    - one or more occurrences of the preceding character set
        // $    - end of the string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }
}
