import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Jäsentää HTTP-otsikon.
     * 
     * Funktio validoi otsikon muodon säännöllisen lausekkeen avulla varmistaakseen, että se sisältää vain aakkosnumeerisia merkkejä ja välilyöntejä.
     */
    public String[] parseHeader(String headerLine) {
        // The regex captures the header name (alphanumeric and hyphens) and the header value.
        // The header value is strictly validated to contain only alphanumeric characters and spaces,
        // as specified in the Javadoc.
        // Example: "Content-Type: text html" -> name="Content-Type", value="text html"
        Pattern pattern = Pattern.compile("^([a-zA-Z0-9-]+):\\s*([a-zA-Z0-9 ]*)$");
        Matcher matcher = pattern.matcher(headerLine);

        if (matcher.matches()) {
            String name = matcher.group(1);
            String value = matcher.group(2);
            return new String[]{name, value};
        } else {
            // Return null if the header line does not match the expected format
            // or contains invalid characters in the value part.
            return null;
        }
    }
}
