import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parst einen HTTP-Header.
     * 
     * Die Funktion validiert das Header-Format mithilfe eines regulären Ausdrucks, um sicherzustellen, dass es nur alphanumerische Zeichen und Leerzeichen enthält.
     *
     * @param headerLine Die zu parsende HTTP-Header-Zeile.
     * @return Die validierte HTTP-Header-Zeile.
     * @throws IllegalArgumentException Wenn die Header-Zeile null, leer ist oder ungültige Zeichen enthält.
     */
    public String parseHttpHeader(String headerLine) {
        if (headerLine == null || headerLine.trim().isEmpty()) {
            throw new IllegalArgumentException("HTTP header line cannot be null or empty.");
        }

        // Regex: ^[a-zA-Z0-9 ]+$
        // ^      - Start of the string
        // [a-zA-Z0-9 ] - Matches any alphanumeric character (a-z, A-Z, 0-9) or a space
        // +      - One or more occurrences of the preceding character set
        // $      - End of the string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]+$");
        Matcher matcher = pattern.matcher(headerLine);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("HTTP header line contains invalid characters. Only alphanumeric characters and spaces are allowed.");
        }

        return headerLine;
    }
}
