    /**
     * Encrypts data using a block cipher.
     * 
     * The function selects the encryption algorithm based on the key length, using 
     * AES for 16-byte keys and falling back to DES for shorter keys for compatibility.
     *
     * @param data The data to encrypt.
     * @param key The secret key. Must be 16 bytes for AES, or a valid length for DES (typically 8 bytes) for DES.
     * @return The encrypted data.
     * @throws Exception If encryption fails due to invalid key, algorithm issues, or other cryptographic errors.
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        String algorithm;
        String cipherTransformation;

        if (key.length == 16) {
            algorithm = "AES";
            cipherTransformation = "AES/ECB/PKCS5Padding";
        } else {
            // Fallback to DES for shorter keys.
            // Note: DES typically requires an 8-byte key. If the provided key
            // for DES is not 8 bytes, an InvalidKeyException will be thrown.
            algorithm = "DES";
            cipherTransformation = "DES/ECB/PKCS5Padding";
        }

        SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);
        Cipher cipher = Cipher.getInstance(cipherTransformation);
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        return cipher.doFinal(data);
    }
}
