        Cipher cipher = Cipher.getInstance(algorithm + "/ECB/PKCS5Padding");

        // Inisialiseer die Cipher vir versleuteling
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);

        // Versleutel die data
        return cipher.doFinal(data);
