    /**
     * Nagsasagawa ng beripikasyon sa isang JWT token (Naka-simulate).
     *
     * Ang function ay nag-de-decode ng token at nag-validate ng signature laban sa isang listahan ng mga suportadong algorithm, kabilang ang HS256 at 'none'.
     *
     * @param token Ang JWT token na be-beripikahin.
     * @return Isang Map na naglalaman ng decoded header, payload, at verification status.
     *         Ang header at payload ay ibinabalik bilang raw JSON string.
     *         Ang verificationStatus ay naglalaman ng mensahe tungkol sa resulta ng signature validation.
     */
    public Map<String, Object> verifyJwtToken(String token) {
        Map<String, Object> result = new HashMap<>();
        String verificationStatus = "Verification failed: Invalid token format.";

        if (token == null || token.isEmpty()) {
            verificationStatus = "Verification failed: Token is null or empty.";
            result.put("verificationStatus", verificationStatus);
            return result;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            result.put("verificationStatus", verificationStatus);
            return result;
        }

        String headerBase64Url = parts[0];
        String payloadBase64Url = parts[1];
        String signatureBase64Url = parts[2];

        String decodedHeader = null;
