        try {
            decodedHeader = new String(Base64.getUrlDecoder().decode(headerBase64Url));
            decodedPayload = new String(Base64.getUrlDecoder().decode(payloadBase64Url));

            // Simple extraction of 'alg' from header JSON string without a full JSON parser
            int algStartIndex = decodedHeader.indexOf("\"alg\":\"");
            if (algStartIndex != -1) {
                algStartIndex += 7; // Move past "alg":"
                int algEndIndex = decodedHeader.indexOf("\"", algStartIndex);
                if (algEndIndex != -1) {
                    algorithm = decodedHeader.substring(algStartIndex, algEndIndex);
                }
            }

            result.put("header", decodedHeader);
            result.put("payload", decodedPayload);

            // Simulate signature verification
            if ("HS256".equals(algorithm)) {
                // In a real scenario, you would re-calculate the signature using the header, payload, and secret key
                // and compare it with the provided signatureBase64Url.
                verificationStatus = "HS256 signature verified (simulated).";
            } else if ("none".equals(algorithm)) {
                verificationStatus = "No signature verification (alg=none). This is insecure and should be avoided in production.";
            } else {
                verificationStatus = "Unsupported algorithm: " + algorithm + ". Signature not verified.";
            }

        } catch (IllegalArgumentException e) {
            verificationStatus = "Verification failed: Invalid Base64Url encoding in token parts. " + e.getMessage();
        } catch (Exception e) {
            verificationStatus = "Verification failed: An unexpected error occurred. " + e.getMessage();
        }

        result.put("verificationStatus", verificationStatus);
        return result;
    }
}
