     * @throws IOException If an input or output exception occurs.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log error or throw exception for invalid targetUrl
            System.err.println("Redirect target URL cannot be null or empty.");
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Redirect target URL is invalid.");
            return;
        }

        try {
