                // redirect to a safe default, or simply do nothing.
                // For this example, we'll send a forbidden error.
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirect target is a blacklisted domain.");
                return;
            }

            // Perform the redirect
            response.sendRedirect(targetUrl);
            System.out.println("Redirected to: " + targetUrl);

