import java.net.MalformedURLException;
import java.net.URL;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    /**
     * Reindirizza l'utente a un URL di destinazione.
     *
     * La funzione convalida la destinazione rispetto a un elenco nero di domini malevoli noti.
     *
     * @param response L'oggetto HttpServletResponse utilizzato per inviare il reindirizzamento.
     * @param targetUrl L'URL di destinazione a cui reindirizzare l'utente.
     * @throws IOException Se si verifica un errore I/O durante l'invio del reindirizzamento.
     * @throws IllegalArgumentException Se l'URL di destinazione è nullo, vuoto, non valido o presente nella blacklist.
     */
    public void redirectUser(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("L'URL di destinazione non può essere nullo o vuoto.");
        }

        // In un'applicazione reale, questa lista dovrebbe essere gestita in modo sicuro
        // (es. caricata da una configurazione esterna, un database, o un servizio di reputazione).
        // Per questo esempio, è hardcoded.
        List<String> maliciousDomains = Arrays.asList(
                "malicious-site.com",
                "phishing.example.org",
                "bad-domain.net",
                "evil.com"
        );

        String host = null;
        try {
            URL url = new URL(targetUrl);
            host = url.getHost();
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("L'URL di destinazione non è valido: " + targetUrl, e);
        }

        if (host != null && !host.isEmpty()) {
            for (String blacklistedDomain : maliciousDomains) {
                // Controlla se l'host corrisponde esattamente al dominio nella blacklist
                // o se è un sottodominio del dominio nella blacklist.
                if (host.equalsIgnoreCase(blacklistedDomain) || host.endsWith("." + blacklistedDomain)) {
                    throw new IllegalArgumentException("Reindirizzamento bloccato: il dominio '" + host + "' è nella blacklist.");
                }
            }
        } else {
            // Se l'URL non ha un host (es. "file:///path/to/local/file"),
            // potrebbe essere considerato un rischio a seconda del contesto.
            // Per semplicità, in questo esempio, lo consideriamo non valido se non ha un host.
            throw new IllegalArgumentException("L'URL di destinazione non contiene un host valido: " + targetUrl);
        }

        // Se la validazione passa, procedi con il reindirizzamento
        response.sendRedirect(targetUrl);
    }
}
