        BLACKLISTED_DOMAINS.add("phishing.net");
        BLACKLISTED_DOMAINS.add("bad-actor.org");
        // Voeg hier meer kwaadaardige domeinen toe
    }

    /**
     * Stuur de gebruiker door naar een doel-URL.
     *
     * De functie valideert het doel tegen een zwarte lijst van bekende kwaadaardige domeinen.
     *
     * @param response De {@link HttpServletResponse} om de redirect uit te voeren.
     * @param targetUrl De URL waarnaar de gebruiker moet worden doorgestuurd.
     * @throws IOException Als er een I/O-fout optreedt tijdens de redirect.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        // Definieer een veilige fallback-URL voor het geval het doel op de zwarte lijst staat of ongeldig is
        final String SAFE_FALLBACK_URL = "/error?code=invalid_redirect"; // Of "/home", etc.

        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            // Log deze gebeurtenis voor beveiligingsmonitoring
            System.err.println("Poging tot redirect naar null of lege URL. Doorsturen naar fallback: " + SAFE_FALLBACK_URL);
            response.sendRedirect(SAFE_FALLBACK_URL);
            return;
        }

        // Converteer targetUrl naar kleine letters voor hoofdletterongevoelige matching
        String lowerCaseTargetUrl = targetUrl.toLowerCase();

        // Controleer tegen de zwarte lijst
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            if (lowerCaseTargetUrl.contains(blacklistedDomain.toLowerCase())) {
