import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    // Una lista negra de dominios maliciosos conocidos.
    // En un entorno de producción, esta lista debería ser gestionada de forma segura
    // y posiblemente cargada desde una fuente externa o base de datos.
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        // Inicializar la lista negra con algunos dominios de ejemplo.
        // ¡ADVERTENCIA! Estos son solo ejemplos. No confíe en esta lista para seguridad real.
        BLACKLISTED_DOMAINS.add("malicious-site.com");
        BLACKLISTED_DOMAINS.add("phishing.example.org");
        BLACKLISTED_DOMAINS.add("bad-domain.net");
        BLACKLISTED_DOMAINS.add("evil-server.info");
        // Agregue más dominios según sea necesario.
    }

    /**
     * Redirige al usuario a una URL de destino.
     *
     * La función valida el destino contra una lista negra de dominios maliciosos conocidos.
     * Si la URL de destino es nula, vacía, malformada o su dominio está en la lista negra,
     * la redirección no se realizará y se registrará un error.
     *
     * @param response El objeto HttpServletResponse utilizado para realizar la redirección.
     * @param targetUrl La URL completa a la que se debe redirigir al usuario.
     * @return true si la redirección fue intentada y permitida, false si fue bloqueada o hubo un error de validación.
     * @throws IOException Si ocurre un error de E/S durante la operación de redirección (e.g., el cliente ya ha enviado la respuesta).
     */
    public boolean redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            System.err.println("ERROR: La URL de destino no puede ser nula o vacía.");
            return false;
        }

        String domain = null;
        try {
            URL url = new URL(targetUrl);
            domain = url.getHost(); // Obtiene el nombre de host (dominio o IP)
        } catch (MalformedURLException e) {
            System.err.println("ERROR: La URL de destino '" + targetUrl + "' está malformada. " + e.getMessage());
            return false; // No se puede validar una URL malformada, así que se bloquea.
        }

        // Si el dominio es nulo (ej. para URLs como "file:///"), o si está en la lista negra.
        if (domain == null || BLACKLISTED_DOMAINS.contains(domain.toLowerCase())) {
            System.err.println("ADVERTENCIA: Redirección bloqueada. El dominio '" + domain + "' de la URL '" + targetUrl + "' está en la lista negra o es inválido.");
            return false;
        }

        try {
            response.sendRedirect(targetUrl);
            System.out.println("INFO: Redirigido exitosamente a: " + targetUrl);
            return true;
        } catch (IOException e) {
            System.err.println("ERROR: Fallo al redirigir a '" + targetUrl + "': " + e.getMessage());
            throw e; // Re-lanzar la excepción para que el llamador pueda manejarla.
        }
    }
}

