import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * Lädt die Konfiguration aus einem YAML-String.
     * 
     * Die Funktion überprüft auf explizite gefährliche Tags, um die
     * Objektinstanziierung zu verhindern.
     *
     * @param yamlString Der YAML-String, der geladen werden soll.
     * @return Das geladene Konfigurationsobjekt (z.B. eine Map oder eine Liste von Primitiven).
     * @throws YAMLException Wenn ein Fehler beim Parsen des YAML auftritt oder gefährliche Tags erkannt werden.
     */
    public Object loadConfiguration(String yamlString) throws YAMLException {
        // Verwende SafeConstructor, um die Instanziierung beliebiger Java-Objekte zu verhindern.
        // SafeConstructor erlaubt nur primitive Typen, Listen, Maps und Sets.
        // Es lehnt explizit benutzerdefinierte Java-Objekt-Tags wie !!java.lang.Object oder !!my.package.MyClass ab.
        Yaml yaml = new Yaml(new SafeConstructor());

        try {
            // Lade den YAML-String.
            // SafeConstructor wirft eine YAMLException, wenn es auf ein nicht unterstütztes Tag trifft.
            return yaml.load(yamlString);
        } catch (YAMLException e) {
            // Fange die SnakeYAML-Fehler ab und werfe sie ggf. mit einer spezifischeren Nachricht erneut.
            throw new YAMLException("Fehler beim Laden der YAML-Konfiguration oder potenziell gefährliche Tags erkannt.", e);
        }
    }
}
