        // Use SafeConstructor to prevent arbitrary object creation from dangerous tags.
        // SafeConstructor only allows basic Java types (String, Integer, List, Map, etc.)
        // and explicitly defined types via addTypeDescription if needed, but by default,
        // it's designed to be safe against deserialization attacks.
        Yaml yaml = new Yaml(new SafeConstructor());
        return yaml.loadAs(yamlString, type);
    }
}
