public class ClassX {
    /**
     * Laadt configuratie vanuit een YAML-string.
     *
     * De functie controleert op expliciete gevaarlijke tags om objectinstantiatie te voorkomen.
     *
     * @param yamlString De YAML-string die moet worden geladen.
     * @param type Het Class-object dat het type van de te laden configuratie vertegenwoordigt.
     * @param <T> Het generieke type van de configuratie.
     * @return Een object van het opgegeven type, gevuld met de configuratiewaarden.
     * @throws YAMLException Als er een fout optreedt tijdens het parsen of als gevaarlijke tags worden gedetecteerd.
     */
    public <T> T loadConfigFromString(String yamlString, Class<T> type) throws YAMLException {
        // Gebruik SafeConstructor om gevaarlijke tags en arbitraire objectinstantiatie te voorkomen.
        // SafeConstructor staat alleen een beperkte set van veilige Java-typen toe (primitieven, String, List, Map, Set).
        // Het voorkomt het laden van willekeurige Java-objecten via tags zoals !!java.object.
        Yaml yaml = new Yaml(new SafeConstructor());

        try {
            return yaml.loadAs(yamlString, type);
        } catch (YAMLException e) {
            // Vang specifieke YAML-gerelateerde fouten op, inclusief die veroorzaakt door onveilige tags.
            throw new YAMLException("Fout bij het laden van YAML-configuratie: " + e.getMessage(), e);
        }
    }
}
