import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.error.YAMLException;

import java.util.Map;

public class ClassX {
    /**
     * Charge la configuration à partir d'une chaîne YAML.
     *
     * La fonction vérifie les balises dangereuses explicites pour empêcher l'instanciation d'objets.
     *
     * @param yamlString La chaîne YAML à charger.
     * @return Un objet représentant la configuration chargée (généralement une Map ou une List).
     * @throws YAMLException Si la chaîne YAML est mal formée ou contient des balises dangereuses.
     */
    public Object loadConfig(String yamlString) throws YAMLException {
        // Utilise SafeConstructor pour empêcher l'instanciation d'objets arbitraires
        // via des balises comme !!java.lang.Object ou !!javax.script.ScriptEngineManager.
        // SafeConstructor ne permet que l'instanciation de types Java de base
        // (String, Integer, Map, List, etc.) et de quelques types spécifiques.
        Constructor constructor = new SafeConstructor();
        Yaml yaml = new Yaml(constructor);

        // Charge la configuration. Si des balises dangereuses sont présentes,
        // SafeConstructor lèvera une exception.
        return yaml.load(yamlString);
    }

    /**
     * Charge la configuration à partir d'une chaîne YAML dans une classe spécifique.
     *
     * Cette méthode utilise SafeConstructor pour empêcher l'instanciation d'objets arbitraires
     * tout en permettant le chargement dans une classe de destination spécifiée.
     *
     * @param yamlString La chaîne YAML à charger.
     * @param type La classe de destination dans laquelle charger la configuration.
     * @param <T> Le type de la classe de destination.
     * @return Un objet de type T représentant la configuration chargée.
     * @throws YAMLException Si la chaîne YAML est mal formée, contient des balises dangereuses
     *                       ou ne peut pas être mappée à la classe spécifiée.
     */
    public <T> T loadConfigAs(String yamlString, Class<T> type) throws YAMLException {
        // Pour charger dans un type spécifique tout en restant sécurisé,
        // on peut étendre SafeConstructor ou utiliser un constructeur personnalisé
        // qui autorise le type cible mais restreint les autres.
        // Pour une sécurité maximale, SafeConstructor est la base.
        // Si le type 'type' est un POJO, SafeConstructor peut le gérer si ses champs
        // sont des types de base ou des collections de types de base.
        // Si le POJO lui-même est considéré comme "dangereux" par SafeConstructor,
        // il faudra un constructeur plus permissif mais contrôlé.
        // Pour cet exemple, nous utilisons SafeConstructor qui est restrictif par défaut.
        // Si le type 'type' n'est pas un type de base ou un Map/List,
        // SafeConstructor pourrait échouer à moins qu'il ne soit explicitement configuré.
        // Une approche plus robuste pour des POJOs spécifiques serait de créer un
        // constructeur personnalisé qui hérite de SafeConstructor et ajoute des
        // constructeurs pour les types de POJO spécifiques.
        // Cependant, pour l'objectif de "prévenir l'instanciation d'objets arbitraires",
        // SafeConstructor est le choix le plus direct.

        // Pour permettre le chargement d'un POJO spécifique tout en bloquant les autres,
        // on pourrait utiliser un constructeur personnalisé comme suit :
        // class CustomConstructor extends SafeConstructor {
        //     public CustomConstructor() {
        //         super();
        //         this.addTypeDescription(new TypeDescription(type));
        //     }
        // }
        // Yaml yaml = new Yaml(new CustomConstructor());
        // return yaml.loadAs(yamlString, type);

        // Pour la simplicité et l'adhérence à "vérifie les balises dangereuses explicites",
        // nous utilisons SafeConstructor directement. Il gérera les types de base, Map, List.
        // Si 'type' est un POJO, SnakeYAML essaiera de le construire si SafeConstructor
        // le permet (ce qui est souvent le cas pour des POJOs simples sans balises explicites).
        Constructor constructor = new SafeConstructor();
        Yaml yaml = new Yaml(constructor);
        return yaml.loadAs(yamlString, type);
    }
}
