import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * Laeb konfiguratsiooni YAML stringist.
     *
     * Funktsioon kontrollib selgelt ohtlike silte, et vältida objekti instantsi loomist.
     * See saavutatakse kasutades SnakeYAML-i {@link SafeConstructor}, mis piirab lubatud YAML-silte
     * ja takistab suvaliste Java objektide deserialiseerimist, mis võiks viia turvaaukudeni.
     *
     * @param <T> Konfiguratsiooni klassi tüüp.
     * @param yamlString YAML string, mis sisaldab konfiguratsiooni.
     * @param type Konfiguratsiooni klassi tüüp, kuhu YAML laadida.
     * @return Laetud konfiguratsiooni objekt.
     * @throws YAMLException Kui YAML on vigane või sisaldab ohtlikke/keelatud silte,
     *                       mida {@link SafeConstructor} ei luba.
     */
    public <T> T loadConfiguration(String yamlString, Class<T> type) throws YAMLException {
        // Kasutame SafeConstructorit, mis on loodud turvaliseks YAML-i laadimiseks.
        // See lubab ainult skalaare, liste ja mappe, vältides suvaliste Java objektide loomist.
        Yaml yaml = new Yaml(new SafeConstructor());

        try {
            // Laeme YAML stringi etteantud tüüpi objektiks.
            // SafeConstructor tagab, et ainult ohutud struktuurid on lubatud.
            return yaml.loadAs(yamlString, type);
        } catch (YAMLException e) {
            // Püüame kinni kõik SnakeYAML-i poolt visatud erandid,
            // mis võivad viidata vigasele YAML-ile või keelatud struktuuridele.
            throw new YAMLException("Viga konfiguratsiooni laadimisel YAML stringist: " + e.getMessage(), e);
        }
    }
}
