import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.error.YAMLException;
import org.yaml.snakeyaml.nodes.Tag;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    /**
     * Φορτώνει τη διαμόρφωση από μια συμβολοσειρά YAML.
     *
     * Η συνάρτηση ελέγχει για τις ρητές επικίνδυνες ετικέτες για να αποτρέψει
     * την δημιουργία αντικειμένων.
     *
     * @param yamlString Η συμβολοσειρά YAML που περιέχει τη διαμόρφωση.
     * @param type Η κλάση στην οποία θα γίνει η αντιστοίχιση της διαμόρφωσης.
     * @param <T> Ο τύπος της κλάσης στην οποία θα γίνει η αντιστοίχιση.
     * @return Ένα αντικείμενο του τύπου T με τη φορτωμένη διαμόρφωση.
     * @throws YAMLException Εάν η συμβολοσειρά YAML περιέχει επικίνδυνες ετικέτες ή είναι εσφαλμένη.
     */
    public <T> T loadConfiguration(String yamlString, Class<T> type) throws YAMLException {
        // Define a set of explicitly dangerous tags
        Set<Tag> dangerousTags = new HashSet<>(Arrays.asList(
                Tag.JAVA_OBJECT,
                Tag.MERGE, // While not directly object creation, can lead to unexpected behavior
                new Tag("!!javax.script.ScriptEngineManager"),
                new Tag("!!java.net.URL"),
                new Tag("!!java.net.URI"),
                new Tag("!!java.nio.file.Path"),
                new Tag("!!java.time.Instant"), // Can be used in conjunction with other tags
                new Tag("!!org.yaml.snakeyaml.constructor.Constructor"),
                new Tag("!!org.yaml.snakeyaml.Yaml"),
                new Tag("!!java.beans.XMLEncoder"),
                new Tag("!!java.lang.ProcessBuilder"),
                new Tag("!!java.lang.Runtime")
                // Add more specific dangerous tags as needed
        ));

        Constructor constructor = new Constructor(type);

        // Override the default tag handling to explicitly check for dangerous tags
        constructor.addTagValidator(tag -> {
            if (dangerousTags.contains(tag)) {
                throw new YAMLException("Dangerous tag found: " + tag.getValue() + ". Object creation is disallowed.");
            }
        });

        Yaml yaml = new Yaml(constructor);

        try {
            return yaml.load(yamlString);
        } catch (YAMLException e) {
            throw new YAMLException("Failed to load YAML configuration: " + e.getMessage(), e);
        }
    }
}
