import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Parst ein XML-Dokument.
     * 
     * Die Funktion überprüft das Vorhandensein von 'DOCTYPE'-Deklarationen, um XXE zu verhindern.
     *
     * @param xmlString Der zu parsende XML-String.
     * @return Das geparste XML-Dokument.
     * @throws ParserConfigurationException Wenn ein Problem mit der Parser-Konfiguration auftritt.
     * @throws SAXException Wenn ein SAX-Fehler während des Parsens auftritt.
     * @throws IOException Wenn ein E/A-Fehler auftritt.
     */
    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // XXE-Prävention: Deaktiviert DOCTYPE-Deklarationen
        // Dies verhindert das Laden externer Entitäten und somit XXE-Angriffe.
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Weitere allgemeine XXE-Präventionen (empfohlen)
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // Optional: Ignoriere Kommentare und Whitespace, falls nicht benötigt
        dbf.setIgnoringComments(true);
        dbf.setIgnoringElementContentWhitespace(true);

        DocumentBuilder db = dbf.newDocumentBuilder();

        // Parsen des XML-Strings
        // Verwenden von StandardCharsets.UTF_8 für konsistente Zeichenkodierung
        return db.parse(new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8)));
    }
}
