     * @throws SAXException Se houver um erro de análise XML.
     * @throws IOException Se houver um erro de I/O ao ler o XML.
     */
    public Document parseXml(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configurações para prevenir XXE (XML External Entity)
        // 1. Habilita o processamento seguro, que geralmente desabilita algumas funcionalidades perigosas.
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // 2. Desabilita a declaração DOCTYPE para prevenir a inclusão de DTDs externas.
        //    Esta é uma das principais defesas contra XXE.
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            // Ignorar se o parser não suportar esta feature específica (ex: não é Apache Xerces)
            // No entanto, as outras features ainda fornecem proteção.
        }

        // 3. Desabilita entidades gerais externas.
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

        // 4. Desabilita entidades de parâmetros externas.
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 5. Desabilita a expansão de referências de entidade.
        factory.setExpandEntityReferences(false);

        // 6. Desabilita XInclude.
        factory.setXIncludeAware(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Analisa o XML a partir de um ByteArrayInputStream
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlContent.getBytes("UTF-8"))) {
            return builder.parse(input);
