public class ClassX {

    // Simüle edilmiş geçerli anahtar. Gerçek uygulamada bu, güvenli bir şekilde yönetilmelidir.
    private static final String VALID_API_KEY = "mySuperSecretAPIKey123";

    /**
     * Dış bir API'ye bağlanarak anahtarı kontrol eder (Simüle Edildi).
