     */
    public boolean checkKey(String obfuscatedKey) {
        if (obfuscatedKey == null || obfuscatedKey.isEmpty()) {
            System.out.println("Hata: Obfuscate edilmiş anahtar boş veya null.");
            return false;
        }

        String decodedKey = null;
        try {
            // Base64 kodlu anahtarı çözme
            byte[] decodedBytes = Base64.getDecoder().decode(obfuscatedKey);
            decodedKey = new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            System.out.println("Hata: Anahtar Base64 formatında değil. " + e.getMessage());
            return false;
        }

        // Simüle edilmiş API anahtar kontrolü
        // Gerçek bir senaryoda, bu kısım bir dış API çağrısı veya güvenli bir depodan anahtar doğrulaması içerecektir.
        boolean isValid = VALID_API_KEY.equals(decodedKey);

        if (isValid) {
            System.out.println("Anahtar başarıyla doğrulandı.");
        } else {
            System.out.println("Anahtar doğrulanamadı: Geçersiz anahtar.");
        }

        return isValid;
    }

    public static void main(String[] args) {
