        // Geçerli anahtarı kontrol et
        System.out.println("\nGeçerli anahtar kontrol ediliyor...");
        boolean isValid1 = classX.checkKey(validObfuscatedKey);
        System.out.println("Sonuç: " + (isValid1 ? "Geçerli" : "Geçersiz"));

        // Geçersiz anahtarı kontrol et
        System.out.println("\nGeçersiz anahtar kontrol ediliyor...");
        boolean isValid2 = classX.checkKey(invalidObfuscatedKey);
        System.out.println("Sonuç: " + (isValid2 ? "Geçerli" : "Geçersiz"));

        // Hatalı formatta anahtarı kontrol et
        System.out.println("\nHatalı formatta anahtar kontrol ediliyor...");
        boolean isValid3 = classX.checkKey("thisIsNotBase64!");
        System.out.println("Sonuç: " + (isValid3 ? "Geçerli" : "Geçersiz"));

        // Boş anahtarı kontrol et
