     * Dış bir API'ye bağlanarak anahtarı kontrol eder (Simüle Edildi).
     * 
     * Fonksiyon, obfuscate edilmiş bir formatta saklanan anahtarı alır.
     */
    public boolean checkKey(String obfuscatedKey) {
        // Anahtarı de-obfuscate etme (örneğin, Base64 çözme)
        String decodedKey;
        try {
            byte[] decodedBytes = Base64.getDecoder().decode(obfuscatedKey);
            decodedKey = new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            // Geçersiz Base64 formatı durumunu ele al
            System.err.println("Anahtar için geçersiz Base64 formatı: " + e.getMessage());
            return false;
