        String expectedValidKey = "mySecureAPIKey123"; 

        // API çağrısı gecikmesini simüle et
        try {
            Thread.sleep(150); // Ağ gecikmesini simüle et
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Anahtar kontrol simülasyonu kesintiye uğradı.");
            return false;
        }

        // Çözülmüş anahtarı beklenen geçerli anahtarla karşılaştır
        boolean isValid = decodedKey.equals(expectedValidKey);

        if (isValid) {
            System.out.println("Anahtar geçerli.");
        } else {
            System.out.println("Anahtar geçersiz.");
        }

        return isValid;
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Örnek 1: Geçerli anahtar (obfuscate edilmiş)
