        System.out.println("Geçerli anahtar kontrol ediliyor: " + obfuscatedValidKey);
        boolean result1 = classX.checkKey(obfuscatedValidKey); // true dönmeli
        System.out.println("Geçerli anahtar için sonuç: " + result1);
        System.out.println("--------------------");

        // Örnek 2: Geçersiz anahtar (obfuscate edilmiş)
        String invalidKey = "wrongKey456";
        String obfuscatedInvalidKey = Base64.getEncoder().encodeToString(invalidKey.getBytes());
        System.out.println("Geçersiz anahtar kontrol ediliyor: " + obfuscatedInvalidKey);
        boolean result2 = classX.checkKey(obfuscatedInvalidKey); // false dönmeli
        System.out.println("Geçersiz anahtar için sonuç: " + result2);
        System.out.println("--------------------");

