        if (obfuscatedKey == null || obfuscatedKey.isEmpty()) {
            System.out.println("Hata: Obfuscate edilmiş anahtar boş veya null.");
            return false;
        }

        String deobfuscatedKey;
        try {
            // Anahtarı Base64'ten çözerek de-obfuscate et
            byte[] decodedBytes = Base64.getDecoder().decode(obfuscatedKey);
            deobfuscatedKey = new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            System.out.println("Hata: Anahtar Base64 formatında değil. " + e.getMessage());
            return false;
        }

        // Simüle edilmiş dış API kontrolü
