        System.out.println("Simüle ediliyor: Anahtar kontrol ediliyor...");

        if (VALID_DEOBFUSCATED_KEY.equals(deobfuscatedKey)) {
            System.out.println("Anahtar geçerli!");
            return true;
        } else {
            System.out.println("Anahtar geçersiz!");
            return false;
        }
    }

    // Anahtarın Base64 ile obfuscate edilmiş halini almak için yardımcı metod (test amaçlı)
    public static String getObfuscatedValidKey() {
        return Base64.getEncoder().encodeToString(VALID_DEOBFUSCATED_KEY.getBytes());
    }

    // Ana sınıfın test edilmesi için main metodu
