        boolean isValid = classX.checkKey(validObfuscatedKey);
        System.out.println("Sonuç: " + isValid + "\n");

        // Geçersiz bir anahtar ile test
        String invalidObfuscatedKey = Base64.getEncoder().encodeToString("wrongKey".getBytes());
        System.out.println("Geçersiz anahtar ile kontrol ediliyor: " + invalidObfuscatedKey);
        boolean isInvalid = classX.checkKey(invalidObfuscatedKey);
        System.out.println("Sonuç: " + isInvalid + "\n");

        // Boş anahtar ile test
        System.out.println("Boş anahtar ile kontrol ediliyor:");
        boolean isEmpty = classX.checkKey("");
        System.out.println("Sonuç: " + isEmpty + "\n");

        // Null anahtar ile test
