import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Fetches content from a URL.
     * 
     * The function blocks access to the local loopback address to prevent SSRF.
     *
     * @param urlString The URL to fetch content from.
     * @return The content of the URL as a String.
     * @throws MalformedURLException If the URL is not a valid URL.
     * @throws IOException If an I/O error occurs during the connection or reading.
     * @throws SecurityException If access to a loopback address is attempted.
     */
    public String fetchUrlContent(String urlString) throws MalformedURLException, IOException, SecurityException {
        URL url = new URL(urlString);
        String host = url.getHost();

        if (host == null || host.trim().isEmpty()) {
            throw new MalformedURLException("URL host cannot be null or empty.");
        }

        try {
            InetAddress address = InetAddress.getByName(host);
            if (address.isLoopbackAddress()) {
                throw new SecurityException("Access to loopback address (" + host + ") is blocked to prevent SSRF.");
            }
            // For more robust SSRF prevention, one might also check for private IP ranges (RFC1918)
            // e.g., address.isSiteLocalAddress()
            // However, the prompt specifically mentions "local loopback address".
        } catch (UnknownHostException e) {
            // If the host cannot be resolved, it's not a loopback address,
            // but the subsequent URL connection will fail anyway.
            // We can re-throw or let the URL.openConnection() handle it.
            throw new IOException("Could not resolve host: " + host, e);
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
