import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Busca conteúdo de uma URL.
     *
     * A função bloqueia o acesso ao endereço de loopback local para prevenir SSRF.
     *
     * @param urlString A URL para buscar o conteúdo.
     * @return O conteúdo da URL como uma String.
     * @throws MalformedURLException Se a URL for malformada.
     * @throws IOException Se ocorrer um erro de I/O ao conectar ou ler da URL.
     * @throws SecurityException Se a URL tentar acessar um endereço de loopback.
     */
    public String fetchUrlContent(String urlString) throws MalformedURLException, IOException, SecurityException {
        URL url = new URL(urlString);

        // Extrai o host da URL
        String host = url.getHost();

        // Verifica se o host resolve para um endereço de loopback
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (addr.isLoopbackAddress()) {
                    throw new SecurityException("Acesso a endereços de loopback (" + host + ") é bloqueado para prevenir SSRF.");
                }
            }
        } catch (UnknownHostException e) {
            // Se o host não puder ser resolvido, não é um endereço de loopback local.
            // A conexão URL falhará posteriormente se o host for realmente inatingível.
            // Não há necessidade de lançar uma exceção de segurança aqui.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
